function extractJson(text) {
	// Remove markdown code blocks if present
	let jsonText = text.trim();

	// Remove ```json blocks
	jsonText = jsonText.replace(/^```json\s*/gm, '');
	jsonText = jsonText.replace(/^```\s*/gm, '');
	jsonText = jsonText.replace(/```\s*$/gm, '');

	// Remove common TypeScript/JavaScript patterns
	jsonText = jsonText.replace(/^const\s+\w+\s*=\s*/, ''); // Remove "const varName = "
	jsonText = jsonText.replace(/^let\s+\w+\s*=\s*/, ''); // Remove "let varName = "
	jsonText = jsonText.replace(/^var\s+\w+\s*=\s*/, ''); // Remove "var varName = "
	jsonText = jsonText.replace(/;?\s*$/, ''); // Remove trailing semicolons

	// Remove explanatory text before JSON (common with AI responses)
	jsonText = jsonText.replace(/^.*?(?=\{|\[)/s, '');

	// Remove explanatory text after JSON
	const lines = jsonText.split('\n');
	let jsonEndIndex = -1;
	let braceCount = 0;
	let inString = false;
	let escapeNext = false;

	// Find the end of the JSON by tracking braces
	for (let i = 0; i < jsonText.length; i++) {
		const char = jsonText[i];

		if (escapeNext) {
			escapeNext = false;
			continue;
		}

		if (char === '\\') {
			escapeNext = true;
			continue;
		}

		if (char === '"' && !escapeNext) {
			inString = !inString;
			continue;
		}

		if (!inString) {
			if (char === '{' || char === '[') {
				braceCount++;
			} else if (char === '}' || char === ']') {
				braceCount--;
				if (braceCount === 0) {
					jsonEndIndex = i;
					break;
				}
			}
		}
	}

	if (jsonEndIndex > -1) {
		jsonText = jsonText.substring(0, jsonEndIndex + 1);
	}

	// Try to extract JSON object or array if previous method didn't work
	if (jsonEndIndex === -1) {
		const objectMatch = jsonText.match(/{[\s\S]*}/);
		const arrayMatch = jsonText.match(/\[[\s\S]*\]/);

		if (objectMatch) {
			jsonText = objectMatch[0];
		} else if (arrayMatch) {
			jsonText = arrayMatch[0];
		}
	}

	// First try to parse as valid JSON
	try {
		JSON.parse(jsonText);
		return jsonText;
	} catch {
		// If it's not valid JSON, it might be a JavaScript object literal
		// Try to convert it to valid JSON
		try {
			// This is a simple conversion that handles basic cases
			// Replace unquoted keys with quoted keys
			const converted = jsonText
				.replace(/([{,]\s*)([a-zA-Z_$][a-zA-Z0-9_$]*)\s*:/g, '$1"$2":')
				// Replace single quotes with double quotes
				.replace(/'/g, '"')
				// Handle trailing commas
				.replace(/,\s*([}\]])/g, '$1');

			// Validate the converted JSON
			JSON.parse(converted);
			return converted;
		} catch {
			// If all else fails, return the original text
			// The calling code will handle the error appropriately
			return text;
		}
	}
}

async function updateTaskByIdDirect(args, log, context = {}) {
	const { session } = context;
	// Destructure expected args, including projectRoot and metadata
	const {
		tasksJsonPath,
		id,
		prompt,
		research,
		append,
		metadata,
		projectRoot,
		tag
	} = args;

	const logWrapper = createLogWrapper(log);

	try {
		logWrapper.info(
			`Updating task by ID via direct function. ID: ${id}, ProjectRoot: ${projectRoot}`
		);

		// Check required parameters (id and prompt)
		if (!id) {
			const errorMessage =
				'No task ID specified. Please provide a task ID to update.';
			logWrapper.error(errorMessage);
			return {
				success: false,
				error: { code: 'INPUT_VALIDATION_ERROR', message: errorMessage }
			};
		}

		// At least prompt or metadata is required (validated in MCP tool layer)
		if (!prompt && !metadata) {
			const errorMessage =
				'No prompt or metadata specified. Please provide a prompt with new information or metadata for the task update.';
			logWrapper.error(errorMessage);
			return {
				success: false,
				error: { code: 'INPUT_VALIDATION_ERROR', message: errorMessage }
			};
		}

		// Parse taskId - handle numeric, alphanumeric, and subtask IDs
		let taskId;
		if (typeof id === 'string') {
			// Keep ID as string - supports numeric (1, 2), alphanumeric (TAS-49, JIRA-123), and subtask IDs (1.2, TAS-49.1)
			taskId = id;
		} else if (typeof id === 'number') {
			// Convert number to string for consistency
			taskId = String(id);
		} else {
			const errorMessage = `Invalid task ID type: ${typeof id}. Task ID must be a string or number.`;
			logWrapper.error(errorMessage);
			return {
				success: false,
				error: { code: 'INPUT_VALIDATION_ERROR', message: errorMessage }
			};
		}

		// Resolve tasks.json path - use provided or find it
		const tasksPath =
			tasksJsonPath ||
			findTasksPath({ projectRoot, file: args.file }, logWrapper);
		if (!tasksPath) {
			const errorMessage = 'tasks.json path could not be resolved.';
			logWrapper.error(errorMessage);
			return {
				success: false,
				error: { code: 'INPUT_VALIDATION_ERROR', message: errorMessage }
			};
		}

		// Get research flag
		const useResearch = research === true;

		logWrapper.info(
			`Updating task with ID ${taskId} with prompt "${prompt || '(metadata-only)'}" and research: ${useResearch}`
		);

		const wasSilent = isSilentMode();
		if (!wasSilent) {
			enableSilentMode();
		}

		try {
			// Call legacy script which handles both API and file storage via bridge
			const coreResult = await updateTaskById(
				tasksPath,
				taskId,
				prompt,
				useResearch,
				{
					mcpLog: logWrapper,
					session,
					projectRoot,
					tag,
					commandName: 'update-task',
					outputType: 'mcp',
					metadata
				},
				'json',
				append || false
			);

			// Check if the core function returned null or an object without success
			if (!coreResult || coreResult.updatedTask === null) {
				const message = `Task ${taskId} was not updated (likely already completed).`;
				logWrapper.info(message);
				return {
					success: true,
					data: {
						message: message,
						taskId: taskId,
						updated: false,
						telemetryData: coreResult?.telemetryData,
						tagInfo: coreResult?.tagInfo
					}
				};
			}

			const successMessage = `Successfully updated task with ID ${taskId} based on the prompt`;
			logWrapper.info(successMessage);
			return {
				success: true,
				data: {
					message: successMessage,
					taskId: taskId,
					tasksPath: tasksPath,
					useResearch: useResearch,
					updated: true,
					updatedTask: coreResult.updatedTask,
					telemetryData: coreResult.telemetryData,
					tagInfo: coreResult.tagInfo
				}
			};
		} catch (error) {
			logWrapper.error(`Error updating task by ID: ${error.message}`);
			return {
				success: false,
				error: {
					code: 'UPDATE_TASK_CORE_ERROR',
					message: error.message || 'Unknown error updating task'
				}
			};
		} finally {
			if (!wasSilent && isSilentMode()) {
				disableSilentMode();
			}
		}
	} catch (error) {
		logWrapper.error(`Setup error in updateTaskByIdDirect: ${error.message}`);
		if (isSilentMode()) disableSilentMode();
		return {
			success: false,
			error: {
				code: 'DIRECT_FUNCTION_SETUP_ERROR',
				message: error.message || 'Unknown setup error'
			}
		};
	}
}

