}

function EvalEditableField({
  label,
  value,
  multiline = true,
  onSave,
  placeholder,
  renderPreview, // Optional custom preview renderer
  renderEditor // Optional custom editor renderer (currentValue, onChange) => ReactNode
}) {
  const { t } = useTranslation();
  const theme = useTheme();
  const [editing, setEditing] = useState(false);
  const [editValue, setEditValue] = useState('');

  const handleStartEdit = () => {
    setEditValue(value || '');
    setEditing(true);
  };

  const handleCancel = () => {
    setEditing(false);
    setEditValue('');
  };

  const handleSave = async () => {
    if (onSave) {
      await onSave(editValue);
    }
    setEditing(false);
  };

  return (
    <Box sx={{ mb: 3 }}>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
        <Typography variant="subtitle2" color="text.secondary" sx={{ fontWeight: 600, mr: 1 }}>
          {label}
        </Typography>
        {!editing && (
          <IconButton
            size="small"
            onClick={handleStartEdit}
            sx={{
              color: 'text.disabled',
              '&:hover': { color: 'primary.main' }
            }}
          >
            <EditIcon fontSize="small" />
          </IconButton>
        )}
      </Box>

      {editing ? (
        <Paper variant="outlined" sx={{ p: 2, bgcolor: 'background.default', borderRadius: 2 }}>
          {renderEditor && renderEditor(editValue, setEditValue) ? (
            <Box sx={{ mb: 2 }}>{renderEditor(editValue, setEditValue)}</Box>
          ) : (
            <TextField
              fullWidth
              multiline={multiline}
              minRows={multiline ? 3 : 1}
              maxRows={15}
              value={editValue}
              onChange={e => setEditValue(e.target.value)}
              placeholder={placeholder}
              variant="outlined"
              size="small"
              sx={{ mb: 2 }}
            />
          )}
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
            <Button size="small" startIcon={<CancelIcon />} onClick={handleCancel} color="inherit">
              {t('common.cancel')}
            </Button>
            <Button size="small" variant="contained" startIcon={<SaveIcon />} onClick={handleSave}>
              {t('common.save')}
            </Button>
          </Box>
        </Paper>
      ) : (
        <Box
          sx={{
            p: 2,
            borderRadius: 2,
            border: '1px solid',
            borderColor: 'divider',
            minHeight: 40,
            transition: 'all 0.2s',
            cursor: 'pointer',
            '&:hover': {
              borderColor: 'primary.main',
              bgcolor: alpha(theme.palette.primary.main, 0.02),
              boxShadow: `0 0 0 1px ${theme.palette.primary.main}`
            }
          }}
          onClick={handleStartEdit}
        >
          {renderPreview ? (
            renderPreview(value)
          ) : (
            <Typography
              variant="body1"
              sx={{
                whiteSpace: 'pre-wrap',
                color: value ? 'text.primary' : 'text.disabled',
                fontStyle: value ? 'normal' : 'italic',
                lineHeight: 1.6
              }}
            >
              {value || t('common.noData')}
            </Typography>
          )}
        </Box>
      )}
    </Box>
  );
}

function useEvalTaskDetail(projectId, taskId) {
  const [task, setTask] = useState(null);
  const [results, setResults] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // 分页和筛选状态
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [filterType, setFilterType] = useState(null);
  const [filterCorrect, setFilterCorrect] = useState(null); // null: all, true: correct, false: incorrect
  const [total, setTotal] = useState(0);

  // 加载任务详情
  const loadData = useCallback(async () => {
    if (!projectId || !taskId) return;

    try {
      setLoading(true);
      setError('');

      // 构建查询参数
      const params = new URLSearchParams({
        page: page.toString(),
        pageSize: pageSize.toString()
      });

      if (filterType) {
        params.append('type', filterType);
      }

      if (filterCorrect !== null) {
        params.append('isCorrect', filterCorrect.toString());
      }

      const response = await fetch(`/api/projects/${projectId}/eval-tasks/${taskId}?${params.toString()}`);
      const result = await response.json();

      if (result.code === 0) {
        setTask(result.data.task);
        setResults(result.data.results || []);
        setTotal(result.data.total || 0);
        setStats(result.data.stats);
      } else {
        setError(result.error || '加载失败');
      }
    } catch (err) {
      console.error('加载任务详情失败:', err);
      setError('加载失败');
    } finally {
      setLoading(false);
    }
  }, [projectId, taskId, page, pageSize, filterType, filterCorrect]);

  // 初始加载
  useEffect(() => {
    loadData();
  }, [loadData]);

  // 自动刷新进行中的任务 (仅在第一页且无筛选时刷新，避免干扰用户查看历史记录)
  useEffect(() => {
    if (task?.status !== 0 || page !== 1 || filterType || filterCorrect !== null) return;

    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, [task?.status, page, filterType, filterCorrect, loadData]);

  return {
    task,
    results,
    stats,
    total,
    page,
    setPage,
    pageSize,
    setPageSize,
    filterType,
    setFilterType,
    filterCorrect,
    setFilterCorrect,
    loading,
    error,
    setError,
    loadData
  };
}

function useImageDatasets(projectId, filters = {}) {
  const { t } = useTranslation();
  const [datasets, setDatasets] = useState({ data: [], total: 0 });
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const pageSize = 20;

  // 使用 useMemo 稳定 filters 对象引用
  const stableFilters = useMemo(
    () => ({
      search: filters.search || '',
      confirmed: filters.confirmed,
      minScore: filters.minScore,
      maxScore: filters.maxScore
    }),
    [filters.search, filters.confirmed, filters.minScore, filters.maxScore]
  );

  // 获取数据集列表
  const fetchDatasets = useCallback(async () => {
    try {
      setLoading(true);
      let url = `/api/projects/${projectId}/image-datasets?page=${page}&pageSize=${pageSize}`;

      // 搜索条件
      if (stableFilters.search) {
        url += `&search=${encodeURIComponent(stableFilters.search)}`;
      }

      // 确认状态筛选
      if (stableFilters.confirmed !== undefined) {
        url += `&confirmed=${stableFilters.confirmed}`;
      }

      // 评分筛选
      if (stableFilters.minScore !== undefined || stableFilters.maxScore !== undefined) {
        if (stableFilters.minScore !== undefined) {
          url += `&minScore=${stableFilters.minScore}`;
        }
        if (stableFilters.maxScore !== undefined) {
          url += `&maxScore=${stableFilters.maxScore}`;
        }
      }

      const response = await axios.get(url);
      setDatasets(response.data);
    } catch (error) {
      console.error('Failed to fetch datasets:', error);
      toast.error(t('imageDatasets.fetchFailed', { defaultValue: '获取数据集失败' }));
    } finally {
      setLoading(false);
    }
  }, [projectId, page, pageSize, stableFilters, t]);

  // 删除数据集
  const deleteDataset = useCallback(
    async datasetId => {
      try {
        await axios.delete(`/api/projects/${projectId}/image-datasets/${datasetId}`);
        toast.success(t('imageDatasets.deleteSuccess', { defaultValue: '删除成功' }));
        fetchDatasets();
      } catch (error) {
        console.error('Failed to delete dataset:', error);
        toast.error(t('imageDatasets.deleteFailed', { defaultValue: '删除失败' }));
      }
    },
    [projectId, fetchDatasets, t]
  );

  useEffect(() => {
    if (projectId) {
      fetchDatasets();
    }
  }, [projectId, page, stableFilters, fetchDatasets]);

  return {
    datasets,
    loading,
    page,
    setPage,
    pageSize,
    fetchDatasets,
    deleteDataset
  };
}

function useQuestionDelete(projectId, onDeleteSuccess) {
  const { t } = useTranslation();

  // 确认对话框状态
  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    title: '',
    content: '',
    confirmAction: null
  });

  // 执行单个问题删除
  const executeDeleteQuestion = async (questionId, selectedQuestions, setSelectedQuestions) => {
    toast.promise(axios.delete(`/api/projects/${projectId}/questions/${questionId}`), {
      loading: '数据删除中',
      success: data => {
        // 更新选中状态
        setSelectedQuestions(prev => (prev.includes(questionId) ? prev.filter(id => id !== questionId) : prev));
        // 调用成功回调
        if (onDeleteSuccess) {
          onDeleteSuccess();
        }
        return t('common.deleteSuccess');
      },
      error: error => {
        return error.response?.data?.message || '删除失败';
      }
    });
  };

  // 确认删除单个问题
  const confirmDeleteQuestion = (questionId, selectedQuestions, setSelectedQuestions) => {
    setConfirmDialog({
      open: true,
      title: t('common.confirmDelete'),
      content: t('common.confirmDeleteQuestion'),
      confirmAction: () => executeDeleteQuestion(questionId, selectedQuestions, setSelectedQuestions)
    });
  };

  // 处理删除单个问题的入口函数
  const handleDeleteQuestion = (questionId, selectedQuestions, setSelectedQuestions) => {
    confirmDeleteQuestion(questionId, selectedQuestions, setSelectedQuestions);
  };

  // 执行批量删除问题
  const executeBatchDeleteQuestions = async (selectedQuestions, setSelectedQuestions) => {
    toast.promise(
      axios.delete(`/api/projects/${projectId}/questions/batch-delete`, {
        data: { questionIds: selectedQuestions }
      }),
      {
        loading: `正在删除 ${selectedQuestions.length} 个问题...`,
        success: data => {
          // 调用成功回调
          if (onDeleteSuccess) {
            onDeleteSuccess();
          }
          // 清空选中状态
          setSelectedQuestions([]);
          return `成功删除 ${selectedQuestions.length} 个问题`;
        },
        error: error => {
          return error.response?.data?.message || '批量删除问题失败';
        }
      }
    );
  };

  // 确认批量删除问题
  const confirmBatchDeleteQuestions = (selectedQuestions, setSelectedQuestions) => {
    if (selectedQuestions.length === 0) {
      toast.warning('请先选择问题');
      return;
    }

    setConfirmDialog({
      open: true,
      title: '确认批量删除问题',
      content: `您确定要删除选中的 ${selectedQuestions.length} 个问题吗？此操作不可恢复。`,
      confirmAction: () => executeBatchDeleteQuestions(selectedQuestions, setSelectedQuestions)
    });
  };

  // 处理批量删除问题的入口函数
  const handleBatchDeleteQuestions = (selectedQuestions, setSelectedQuestions) => {
    confirmBatchDeleteQuestions(selectedQuestions, setSelectedQuestions);
  };

  // 关闭确认对话框
  const closeConfirmDialog = () => {
    setConfirmDialog({
      open: false,
      title: '',
      content: '',
      confirmAction: null
    });
  };

  // 确认对话框的确认操作
  const handleConfirmAction = () => {
    closeConfirmDialog();
    if (confirmDialog.confirmAction) {
      confirmDialog.confirmAction();
    }
  };

  return {
    // 状态
    confirmDialog,

    // 方法
    handleDeleteQuestion,
    handleBatchDeleteQuestions,
    closeConfirmDialog,
    handleConfirmAction
  };
}

