function getMaxBytes() {
  const raw = process.env[UPSTREAM_REQUEST_DUMP_MAX_BYTES_ENV]
  if (!raw) {
    return 2 * 1024 * 1024
  }
  const parsed = Number.parseInt(raw, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return 2 * 1024 * 1024
  }
  return parsed
}

function redact(value) {
  if (!value) {
    return value
  }
  const s = String(value)
  if (s.length <= 10) {
    return '***'
  }
  return `${s.slice(0, 3)}...${s.slice(-4)}`
}

function safeJsonStringify(payload, maxBytes) {
  let json = ''
  try {
    json = JSON.stringify(payload)
  } catch (e) {
    return JSON.stringify({
      type: 'antigravity_upstream_dump_error',
      error: 'JSON.stringify_failed',
      message: e?.message || String(e)
    })
  }

  if (Buffer.byteLength(json, 'utf8') <= maxBytes) {
    return json
  }

  const truncated = Buffer.from(json, 'utf8').subarray(0, maxBytes).toString('utf8')
  return JSON.stringify({
    type: 'antigravity_upstream_dump_truncated',
    maxBytes,
    originalBytes: Buffer.byteLength(json, 'utf8'),
    partialJson: truncated
  })
}

async function dumpAntigravityUpstreamRequest(requestInfo) {
  if (!isEnabled()) {
    return
  }

  const maxBytes = getMaxBytes()
  const filename = path.join(getProjectRoot(), UPSTREAM_REQUEST_DUMP_FILENAME)

  const record = {
    ts: new Date().toISOString(),
    type: 'antigravity_upstream_request',
    requestId: requestInfo?.requestId || null,
    model: requestInfo?.model || null,
    stream: Boolean(requestInfo?.stream),
    url: requestInfo?.url || null,
    baseUrl: requestInfo?.baseUrl || null,
    params: requestInfo?.params || null,
    headers: requestInfo?.headers
      ? {
          Host: requestInfo.headers.Host || requestInfo.headers.host || null,
          'User-Agent':
            requestInfo.headers['User-Agent'] || requestInfo.headers['user-agent'] || null,
          Authorization: (() => {
            const raw = requestInfo.headers.Authorization || requestInfo.headers.authorization
            if (!raw) {
              return null
            }
            const value = String(raw)
            const m = value.match(/^Bearer\\s+(.+)$/i)
            const token = m ? m[1] : value
            return `Bearer ${redact(token)}`
          })()
        }
      : null,
    envelope: requestInfo?.envelope || null
  }

  const line = `${safeJsonStringify(record, maxBytes)}\n`
  try {
    await safeRotatingAppend(filename, line)
  } catch (e) {
    logger.warn('Failed to dump Antigravity upstream request', {
      filename,
      requestId: requestInfo?.requestId || null,
      error: e?.message || String(e)
    })
  }
}

async getAccount(accountId) {
    const client = redis.getClientSafe()
    const key = `${this.ACCOUNT_KEY_PREFIX}${accountId}`
    const accountData = await client.hgetall(key)

    if (!accountData || !accountData.id) {
      return null
    }

    // 解密敏感数据
    accountData.apiKey = this._decryptSensitiveData(accountData.apiKey)

    // 解析 JSON 字段
    if (accountData.proxy) {
      try {
        accountData.proxy = JSON.parse(accountData.proxy)
      } catch (e) {
        accountData.proxy = null
      }
    }

    if (accountData.supportedModels) {
      try {
        accountData.supportedModels = JSON.parse(accountData.supportedModels)
      } catch (e) {
        accountData.supportedModels = []
      }
    }

    return accountData
  }

async updateAccount(accountId, updates) {
    const account = await this.getAccount(accountId)
    if (!account) {
      throw new Error('Account not found')
    }

    // 处理敏感字段加密
    if (updates.apiKey) {
      updates.apiKey = this._encryptSensitiveData(updates.apiKey)
    }

    // 处理 JSON 字段
    if (updates.proxy !== undefined) {
      updates.proxy = updates.proxy ? JSON.stringify(updates.proxy) : ''
    }

    if (updates.supportedModels !== undefined) {
      updates.supportedModels = JSON.stringify(updates.supportedModels)
    }

    // 规范化 baseUrl
    if (updates.baseUrl) {
      updates.baseUrl = updates.baseUrl.endsWith('/')
        ? updates.baseUrl.slice(0, -1)
        : updates.baseUrl
    }

    // 更新 Redis
    const client = redis.getClientSafe()
    const key = `${this.ACCOUNT_KEY_PREFIX}${accountId}`
    await client.hset(key, updates)

    logger.info(`📝 Updated Gemini-API account: ${account.name}`)

    return { success: true }
  }

async function handleRequest(request, env, ctx) {
  let response;
  const monitor = new PerformanceMonitor();

  try {
    // Create config with environment variable overrides
    const config = env ? createConfig(env) : CONFIG;
    const url = new URL(request.url);
    const isDocker = isDockerRequest(request, url);

    // Handle Docker API version check
    if (isDocker && (url.pathname === '/v2/' || url.pathname === '/v2')) {
      const headers = new Headers({
        'Docker-Distribution-Api-Version': 'registry/2.0',
        'Content-Type': 'application/json'
      });
      addSecurityHeaders(headers);
      response = new Response('{}', { status: 200, headers });
    }
    // Redirect root path or invalid platforms to GitHub repository
    else if (url.pathname === '/' || url.pathname === '') {
      const HOME_PAGE_URL = 'https://github.com/xixu-me/Xget';
      response = Response.redirect(HOME_PAGE_URL, 302);
    } else {
      const validation = validateRequest(request, url, config);
      if (!validation.valid) {
        response = createErrorResponse(
          validation.error || 'Validation failed',
          validation.status || 400
        );
      } else {
        // Parse platform and path
        let effectivePath = url.pathname;

        // Handle container registry paths specially
        if (isDocker) {
          // For Docker requests, check if they have /cr/ prefix
          // but allow /v2/auth which handles authentication
          if (
            !url.pathname.startsWith('/cr/') &&
            !url.pathname.startsWith('/v2/cr/') &&
            url.pathname !== '/v2/auth'
          ) {
            response = createErrorResponse('container registry requests must use /cr/ prefix', 400);
          } else {
            // Remove /v2 from the path for container registry API consistency if present
            effectivePath = url.pathname.replace(/^\/v2/, '');
          }
        }

        if (!response) {
          // Handle Docker authentication explicitly
          if (isDocker && url.pathname === '/v2/auth') {
            response = await handleDockerAuth(request, url, config);
          } else {
            // Platform detection using transform patterns
            // Use pre-computed sorted platforms
            const platform =
              SORTED_PLATFORMS.find(key => {
                const expectedPrefix = `/${key.replace('-', '/')}/`;
                return effectivePath.startsWith(expectedPrefix);
              }) || effectivePath.split('/')[1];

            if (!platform || !config.PLATFORMS[platform]) {
              const HOME_PAGE_URL = 'https://github.com/xixu-me/Xget';
              response = Response.redirect(HOME_PAGE_URL, 302);
            } else {
              // Check if the path only contains the platform prefix without any actual resource path
              const platformPath = `/${platform.replace(/-/g, '/')}`;
              if (effectivePath === platformPath || effectivePath === `${platformPath}/`) {
                const HOME_PAGE_URL = 'https://github.com/xixu-me/Xget';
                response = Response.redirect(HOME_PAGE_URL, 302);
              } else {
                // Transform URL based on platform using unified logic
                const targetPath = transformPath(effectivePath, platform);

                // For container registries, ensure we add the /v2 prefix for the Docker API
                let finalTargetPath;
                if (platform.startsWith('cr-')) {
                  finalTargetPath = `/v2${targetPath}`;
                } else {
                  finalTargetPath = targetPath;
                }

                const targetUrl = `${config.PLATFORMS[platform]}${finalTargetPath}${url.search}`;
                const authorization = request.headers.get('Authorization');

                // Check if this is a Git operation
                const isGit = isGitRequest(request, url);

                // Check if this is a Git LFS operation
                const isGitLFS = isGitLFSRequest(request, url);

                // Check if this is an AI inference request
                const isAI = isAIInferenceRequest(request, url);

                // Check if this is a Hugging Face API request
                const isHF = isHuggingFaceAPIRequest(request, url);

                // Check cache first (skip cache for Git, Git LFS, Docker, AI inference, and HF API operations)
                /** @type {Cache | null} */
                // @ts-ignore - Cloudflare Workers cache API
                const cache =
                  typeof caches !== 'undefined' && /** @type {any} */ (caches).default // eslint-disable-line jsdoc/reject-any-type
                    ? /** @type {any} */ (caches).default // eslint-disable-line jsdoc/reject-any-type
                    : null;

                if (cache && !isGit && !isGitLFS && !isDocker && !isAI && !isHF) {
                  try {
                    // For Range requests, try cache match first
                    const cacheKey = new Request(targetUrl, {
                      method: 'GET',
                      headers: request.headers
                    });
                    const cachedResponse = await cache.match(cacheKey);
                    if (cachedResponse) {
                      monitor.mark('cache_hit');
                      response = cachedResponse;
                    } else {
                      // If Range request missed cache, try with original request to see if we have full content cached
                      const rangeHeader = request.headers.get('Range');
                      if (rangeHeader) {
                        const fullContentKey = new Request(targetUrl, {
                          method: 'GET', // Always use GET method for cache key consistency
                          headers: new Headers(
                            [...request.headers.entries()].filter(
                              ([k]) => k.toLowerCase() !== 'range'
                            )
                          )
                        });
                        const fullCachedResponse = await cache.match(fullContentKey);
                        if (fullCachedResponse) {
                          monitor.mark('cache_hit_full_content');
                          response = fullCachedResponse;
                        }
                      }
                    }
                  } catch (cacheError) {
                    console.warn('Cache API unavailable:', cacheError);
                  }
                }

                if (!response) {
                  /** @type {RequestInit} */
                  const fetchOptions = {
                    method: request.method,
                    headers: new Headers(),
                    redirect: 'follow'
                  };

                  // Add body for POST/PUT/PATCH/DELETE requests (Git/Docker/AI/HF operations)
                  if (
                    ['POST', 'PUT', 'PATCH', 'DELETE'].includes(request.method) &&
                    (isGit || isGitLFS || isDocker || isAI || isHF)
                  ) {
                    fetchOptions.body = request.body;
                  }

                  // Cast headers to Headers for proper typing
                  const requestHeaders = /** @type {Headers} */ (fetchOptions.headers);

                  // Set appropriate headers for Git/Docker/AI/HF vs regular requests
                  if (isGit || isGitLFS || isDocker || isAI || isHF) {
                    // For Git/Docker/AI/HF operations, copy all headers from the original request
                    // This ensures protocol compliance
                    for (const [key, value] of request.headers.entries()) {
                      // Skip headers that might cause issues with proxying
                      if (
                        !['host', 'connection', 'upgrade', 'proxy-connection'].includes(
                          key.toLowerCase()
                        )
                      ) {
                        requestHeaders.set(key, value);
                      }
                    }

                    // Configure protocol-specific headers using modular helpers
                    configureGitHeaders(requestHeaders, request, url, isGitLFS);

                    if (isAI) {
                      configureAIHeaders(requestHeaders, request);
                    }

                    if (isHF) {
                      configureHuggingFaceHeaders(requestHeaders, request);
                    }
                  } else {
                    // Regular file download headers
                    Object.assign(fetchOptions, {
                      cf: {
                        http3: true,
                        cacheTtl: config.CACHE_DURATION,
                        cacheEverything: true,
                        minify: {
                          javascript: true,
                          css: true,
                          html: true
                        },
                        preconnect: true
                      }
                    });

                    requestHeaders.set('Accept-Encoding', 'gzip, deflate, br');
                    requestHeaders.set('Connection', 'keep-alive');
                    requestHeaders.set('User-Agent', 'Wget/1.21.3');
                    requestHeaders.set('Origin', request.headers.get('Origin') || '*');

                    if (authorization) {
                      requestHeaders.set('Authorization', authorization);
                    }

                    const rangeHeader = request.headers.get('Range');
                    const isMediaFile = targetUrl.match(
                      /\.(mp4|avi|mkv|mov|wmv|flv|webm|mp3|wav|flac|aac|ogg|jpg|jpeg|png|gif|bmp|svg|pdf|zip|rar|7z|tar|gz|bz2|xz)$/i
                    );

                    if (isMediaFile || rangeHeader) {
                      requestHeaders.set('Accept-Encoding', 'identity');
                    }

                    if (rangeHeader) {
                      requestHeaders.set('Range', rangeHeader);
                    }
                  }

                  // Implement retry mechanism
                  let attempts = 0;
                  while (attempts < config.MAX_RETRIES) {
                    try {
                      monitor.mark(`attempt_${attempts}`);

                      const controller = new AbortController();
                      const timeoutId = setTimeout(
                        () => controller.abort(),
                        config.TIMEOUT_SECONDS * 1000
                      );

                      const finalFetchOptions = {
                        ...fetchOptions,
                        signal: controller.signal
                      };

                      // Special handling for Docker redirects to avoid leaking Auth headers to S3 (blobs)
                      if (isDocker) {
                        finalFetchOptions.redirect = 'manual';
                      }

                      // Special handling for HEAD requests to ensure Content-Length header
                      if (request.method === 'HEAD') {
                        response = await fetch(targetUrl, finalFetchOptions);

                        if (response.ok && !response.headers.get('Content-Length')) {
                          const rangeHeaders = new Headers(requestHeaders);
                          rangeHeaders.set('Range', 'bytes=0-0');

                          const rangeResponse = await fetch(targetUrl, {
                            ...finalFetchOptions,
                            method: 'GET',
                            headers: rangeHeaders
                          });

                          let contentLength = null;

                          if (rangeResponse.status === 206) {
                            const contentRange = rangeResponse.headers.get('Content-Range');
                            if (contentRange) {
                              const match = contentRange.match(/bytes\s+\d+-\d+\/(\d+)/);
                              if (match) {
                                [, contentLength] = match;
                              }
                            }
                          } else if (rangeResponse.ok) {
                            contentLength = rangeResponse.headers.get('Content-Length');
                            if (!contentLength) {
                              const sizeLimit = 50 * 1024 * 1024;
                              const contentLengthHint = rangeResponse.headers.get('Content-Length');
                              if (
                                !contentLengthHint ||
                                parseInt(contentLengthHint, 10) < sizeLimit
                              ) {
                                try {
                                  const arrayBuffer = await rangeResponse.arrayBuffer();
                                  contentLength = arrayBuffer.byteLength.toString();
                                } catch (error) {
                                  console.warn(
                                    'Could not buffer response to get Content-Length:',
                                    error
                                  );
                                }
                              }
                            }
                          }

                          if (contentLength) {
                            const headHeaders = new Headers(response.headers);
                            headHeaders.set('Content-Length', contentLength);
                            response = new Response(null, {
                              status: response.status,
                              statusText: response.statusText,
                              headers: headHeaders
                            });
                          }
                        }
                      } else {
                        response = await fetch(targetUrl, finalFetchOptions);
                      }

                      clearTimeout(timeoutId);

                      // Handle manual redirect for Docker
                      if (isDocker && (response.status === 301 || response.status === 302 || response.status === 307)) {
                         const location = response.headers.get('Location');
                         if (location) {
                            // Fetch the new location without Authorization header
                            // Cloudflare Workers fetch should follow this automatically if we used 'follow',
                            // but we used 'manual' to strip headers.
                            const redirectHeaders = new Headers(finalFetchOptions.headers);
                            redirectHeaders.delete('Authorization');

                            response = await fetch(location, {
                              ...finalFetchOptions,
                              headers: redirectHeaders,
                              redirect: 'follow' // Follow subsequent redirects normally
                            });
                         }
                      }

                      if (response.ok || response.status === 206) {
                        monitor.mark('success');
                        break;
                      }

                      // For container registry, handle authentication challenges more intelligently
                      if (isDocker && response.status === 401) {
                        monitor.mark('docker_auth_challenge');

                        const authenticateStr = response.headers.get('WWW-Authenticate');

                        // Calculate scope for upstream token fetch
                        let scope = getScopeFromUrl(url, effectivePath, platform);

                        if (authenticateStr) {
                          try {
                            const wwwAuthenticate = parseAuthenticate(authenticateStr);

                            // Try to get a token for public access (without authorization)
                            const tokenResponse = await fetchToken(
                              wwwAuthenticate,
                              scope || '',
                              ''
                            );

                            if (tokenResponse.ok) {
                              const tokenData = await tokenResponse.json();
                              if (tokenData.token) {
                                const retryHeaders = new Headers(requestHeaders);
                                retryHeaders.set('Authorization', `Bearer ${tokenData.token}`);

                                const retryOptions = {
                                  ...finalFetchOptions,
                                  headers: retryHeaders
                                };

                                // Also use manual redirect for retry
                                if (isDocker) {
                                  retryOptions.redirect = 'manual';
                                }

                                let retryResponse = await fetch(targetUrl, retryOptions);

                                // Handle manual redirect for retry
                                if (isDocker && (retryResponse.status === 301 || retryResponse.status === 302 || retryResponse.status === 307)) {
                                  const location = retryResponse.headers.get('Location');
                                  if (location) {
                                     const redirectHeaders = new Headers(retryOptions.headers);
                                     redirectHeaders.delete('Authorization');

                                     retryResponse = await fetch(location, {
                                       ...retryOptions,
                                       headers: redirectHeaders,
                                       redirect: 'follow'
                                     });
                                  }
                                }

                                if (retryResponse.ok) {
                                  response = retryResponse;
                                  monitor.mark('success');
                                  break;
                                }
                              }
                            }
                          } catch (error) {
                            console.warn('Token fetch failed:', error);
                          }
                        }

                        response = responseUnauthorized(url);
                        break;
                      }

                      if (response.status >= 400 && response.status < 500) {
                        monitor.mark('client_error');
                        break;
                      }

                      attempts++;
                      if (attempts < config.MAX_RETRIES) {
                        await new Promise(resolve =>
                          setTimeout(resolve, config.RETRY_DELAY_MS * attempts)
                        );
                      }
                    } catch (error) {
                      attempts++;
                      if (error instanceof Error && error.name === 'AbortError') {
                        response = createErrorResponse('Request timeout', 408);
                        break;
                      }
                      if (attempts >= config.MAX_RETRIES) {
                        const message = error instanceof Error ? error.message : String(error);
                        response = createErrorResponse(
                          `Failed after ${config.MAX_RETRIES} attempts: ${message}`,
                          500,
                          true
                        );
                        break;
                      }
                      await new Promise(resolve =>
                        setTimeout(resolve, config.RETRY_DELAY_MS * attempts)
                      );
                    }
                  }

                  if (!response) {
                    response = createErrorResponse(
                      'No response received after all retry attempts',
                      500,
                      true
                    );
                  } else if (!response.ok && response.status !== 206) {
                    if (isDocker && response.status === 401) {
                      // Handle Docker 401 responses that might not have been caught by the retry loop
                      const isCustomError =
                        response.headers.get('content-type') === 'application/json' &&
                        (await response.clone().text()).includes('UNAUTHORIZED');

                      if (!isCustomError) {
                        const errorText = await response.text().catch(() => '');
                        response = createErrorResponse(
                          `Authentication required for this container registry resource. This may be a private repository. Original error: ${errorText}`,
                          401,
                          true
                        );
                      }
                    } else {
                      const errorText = await response.text().catch(() => 'Unknown error');
                      response = createErrorResponse(
                        `Upstream server error (${response.status}): ${errorText}`,
                        response.status,
                        true
                      );
                    }
                  } else {
                    // Success case processing (rewriting URLs etc)
                    let responseBody = response.body;

                    if (
                      platform === 'pypi' &&
                      response.headers.get('content-type')?.includes('text/html')
                    ) {
                      const originalText = await response.text();
                      const rewrittenText = originalText.replace(
                        /https:\/\/files\.pythonhosted\.org/g,
                        `${url.origin}/pypi/files`
                      );
                      responseBody = new ReadableStream({
                        start(controller) {
                          controller.enqueue(new TextEncoder().encode(rewrittenText));
                          controller.close();
                        }
                      });
                    }

                    if (
                      platform === 'npm' &&
                      response.headers.get('content-type')?.includes('application/json')
                    ) {
                      const originalText = await response.text();
                      const rewrittenText = originalText.replace(
                        /https:\/\/registry.npmjs.org\/([^/]+)/g,
                        `${url.origin}/npm/$1`
                      );
                      responseBody = new ReadableStream({
                        start(controller) {
                          controller.enqueue(new TextEncoder().encode(rewrittenText));
                          controller.close();
                        }
                      });
                    }

                    const headers = new Headers(response.headers);

                    if (!isGit && !isDocker) {
                      headers.set('Cache-Control', `public, max-age=${config.CACHE_DURATION}`);
                      headers.set('X-Content-Type-Options', 'nosniff');
                      headers.set('Accept-Ranges', 'bytes');

                      if (!headers.has('Content-Length') && response.status === 200) {
                        try {
                          const contentLength = response.headers.get('Content-Length');
                          if (contentLength) {
                            headers.set('Content-Length', contentLength);
                          }
                        } catch (error) {
                          console.warn('Could not set Content-Length header:', error);
                        }
                      }

                      addSecurityHeaders(headers);
                    }

                    response = new Response(responseBody, {
                      status: response.status,
                      headers
                    });

                    // Cache success logic
                    if (
                      cache &&
                      !isGit &&
                      !isGitLFS &&
                      !isDocker &&
                      !isAI &&
                      request.method === 'GET' &&
                      response.ok &&
                      response.status === 200
                    ) {
                      const rangeHeader = request.headers.get('Range');
                      const cacheKey = rangeHeader
                        ? new Request(targetUrl, {
                            method: 'GET',
                            headers: new Headers(
                              [...request.headers.entries()].filter(
                                ([k]) => k.toLowerCase() !== 'range'
                              )
                            )
                          })
                        : new Request(targetUrl, { method: 'GET' });

                      try {
                        if (ctx && typeof ctx.waitUntil === 'function') {
                          ctx.waitUntil(cache.put(cacheKey, response.clone()));
                        } else {
                          cache.put(cacheKey, response.clone()).catch(error => {
                            console.warn('Cache put failed:', error);
                          });
                        }

                        if (rangeHeader && response.status === 200) {
                          const rangedResponse = await cache.match(
                            new Request(targetUrl, {
                              method: 'GET',
                              headers: request.headers
                            })
                          );
                          if (rangedResponse) {
                            monitor.mark('range_cache_hit_after_full_cache');
                            response = rangedResponse;
                          }
                        }
                      } catch (cacheError) {
                        console.warn('Cache put/match failed:', cacheError);
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  } catch (error) {
    console.error('Error handling request:', error);
    const message = error instanceof Error ? error.message : String(error);
    response = createErrorResponse(`Internal Server Error: ${message}`, 500, true);
  }

  // Ensure performance headers are added to the final response
  monitor.mark('complete');
  const isGit = isGitRequest(request, new URL(request.url));
  const isDocker = isDockerRequest(request, new URL(request.url));
  const isAI = isAIInferenceRequest(request, new URL(request.url));
  const isGitLFS = isGitLFSRequest(request, new URL(request.url));
  const isHF = isHuggingFaceAPIRequest(request, new URL(request.url));

  return isGit || isGitLFS || isDocker || isAI || isHF
    ? response
    : addPerformanceHeaders(response, monitor);
}

function transformPath(path, platformKey) {
  // Return original path if platform doesn't exist
  if (!PLATFORMS[platformKey]) {
    return path;
  }

  // Convert platform key to path prefix (e.g., 'ip-openai' -> '/ip/openai/')
  const prefix = `/${platformKey.replace(/-/g, '/')}/`;
  let transformedPath = path.replace(
    new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`),
    '/'
  );

  /**
   * Special handling for crates.io API paths
   *
   * The Rust package registry requires an `/api/v1/crates` prefix for all API endpoints.
   * This transformation adds the necessary prefix to match crates.io's API structure.
   *
   * Transformations:
   * - `/serde/1.0.0/download` -> `/api/v1/crates/serde/1.0.0/download`
   * - `/serde` -> `/api/v1/crates/serde`
   * - `/?q=query` -> `/api/v1/crates?q=query`
   */
  if (platformKey === 'crates') {
    if (transformedPath.startsWith('/')) {
      if (transformedPath === '/' || transformedPath.startsWith('/?')) {
        // Search endpoint: /?q=query -> /api/v1/crates?q=query
        transformedPath = transformedPath.replace('/', '/api/v1/crates');
      } else {
        // Crate-specific endpoints: /serde -> /api/v1/crates/serde
        transformedPath = `/api/v1/crates${transformedPath}`;
      }
    }
  }

  /**
   * Special handling for Homebrew API paths
   *
   * Homebrew API paths are already in the correct format (e.g., /formula/git.json),
   * so we simply strip the prefix and return the path as-is.
   *
   * Supported endpoints:
   * - `/formula/{name}.json` - Formula metadata
   * - `/cask/{name}.json` - Cask metadata
   */
  if (platformKey === 'homebrew-api') {
    if (transformedPath.startsWith('/')) {
      return transformedPath;
    }
  }

  /**
   * Special handling for Homebrew bottles
   *
   * Homebrew bottles are served from GitHub Container Registry (ghcr.io).
   * The paths follow OCI registry format (/v2/...) and are passed through as-is.
   *
   * Example: `/v2/homebrew/core/git/manifests/2.39.0`
   */
  if (platformKey === 'homebrew-bottles') {
    if (transformedPath.startsWith('/')) {
      return transformedPath;
    }
  }

  /**
   * Special handling for Jenkins plugins
   *
   * Jenkins update center requires paths to be prefixed with `/current/` for
   * the default update center. Experimental and download paths are preserved.
   *
   * Transformations:
   * - `/update-center.json` -> `/current/update-center.json`
   * - `/update-center.actual.json` -> `/current/update-center.actual.json`
   * - `/experimental/...` -> `/experimental/...` (preserved)
   * - `/download/...` -> `/download/...` (preserved)
   * - Other paths -> `/current/{path}`
   */
  if (platformKey === 'jenkins') {
    if (transformedPath.startsWith('/')) {
      if (transformedPath === '/update-center.json') {
        return '/current/update-center.json';
      } else if (transformedPath === '/update-center.actual.json') {
        return '/current/update-center.actual.json';
      } else if (
        transformedPath.startsWith('/experimental/') ||
        transformedPath.startsWith('/download/') ||
        transformedPath.startsWith('/current/')
      ) {
        // Keep experimental, download, and current paths as-is
        return transformedPath;
      } else {
        // For other paths, assume they are relative to current
        return `/current${transformedPath}`;
      }
    }
  }

  /**
   * Special handling for Homebrew repositories
   *
   * Homebrew repositories are Git repos on GitHub (github.com/Homebrew).
   * Paths are passed through as-is to access repos like homebrew-core, homebrew-cask.
   *
   * Example: `/brew`, `/homebrew-core`, `/homebrew-cask`
   */
  if (platformKey === 'homebrew') {
    if (transformedPath.startsWith('/')) {
      return transformedPath;
    }
  }

  return transformedPath;
}

function isAIInferenceRequest(request, url) {
  // Check for AI inference provider paths (ip/{provider}/...)
  if (url.pathname.startsWith('/ip/')) {
    return true;
  }

  // Check for common AI inference API endpoints
  const aiEndpoints = [
    '/v1/chat/completions',
    '/v1/completions',
    '/v1/messages',
    '/v1/predictions',
    '/v1/generate',
    '/v1/embeddings',
    '/openai/v1/chat/completions'
  ];

  if (aiEndpoints.some(endpoint => url.pathname.includes(endpoint))) {
    return true;
  }

  // Check for AI-specific content types
  const contentType = request.headers.get('Content-Type') || '';
  if (contentType.includes('application/json') && request.method === 'POST') {
    // Additional check for common AI inference patterns in URL
    if (
      url.pathname.includes('/chat/') ||
      url.pathname.includes('/completions') ||
      url.pathname.includes('/generate') ||
      url.pathname.includes('/predict')
    ) {
      return true;
    }
  }

  return false;
}

function configureAIHeaders(headers, request) {
  if (request.method === 'POST' && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }
  if (!headers.has('User-Agent')) {
    headers.set('User-Agent', 'Xget-AI-Proxy/1.0');
  }
}

function isHuggingFaceAPIRequest(request, url) {
  // Check for Hugging Face API endpoints
  if (url.pathname.startsWith('/hf/api/')) {
    return true;
  }

  // Also check for token endpoint which is often used
  if (url.pathname.startsWith('/hf/token')) {
    return true;
  }

  return false;
}

function configureHuggingFaceHeaders(headers, request) {
  // Pass through Authorization header if present
  if (request.headers.has('Authorization')) {
    headers.set('Authorization', request.headers.get('Authorization'));
  }

  if (request.method === 'POST' && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }
}

async function handler(request) {
  // Extract environment variables from Deno.env
  const env = {
    TIMEOUT_SECONDS: Deno.env.get('TIMEOUT_SECONDS'),
    MAX_RETRIES: Deno.env.get('MAX_RETRIES'),
    RETRY_DELAY_MS: Deno.env.get('RETRY_DELAY_MS'),
    CACHE_DURATION: Deno.env.get('CACHE_DURATION'),
    ALLOWED_METHODS: Deno.env.get('ALLOWED_METHODS'),
    ALLOWED_ORIGINS: Deno.env.get('ALLOWED_ORIGINS'),
    MAX_PATH_LENGTH: Deno.env.get('MAX_PATH_LENGTH'),
  };

  // Create minimal ExecutionContext-like object
  // Deno Deploy doesn't support waitUntil, so cache writes are synchronous
  const ctx = {
    waitUntil: (promise) => {
      // No-op on Deno: background tasks not supported
      console.warn('waitUntil is not supported in Deno Deploy');
    },
    passThroughOnException: () => {
      console.warn('passThroughOnException is not supported in Deno Deploy');
    }
  };

  // Delegate to the main request handler
  return handleRequest(request, env, ctx);
}

async function onRequest(context) {
  // Extract request, env, and create an execution context compatible with Workers
  const { request, env, waitUntil } = context;

  // Create a minimal ExecutionContext-like object for compatibility
  const ctx = {
    waitUntil,
    passThroughOnException: () => {
      // Pages doesn't support passThroughOnException, so this is a no-op
      console.warn('passThroughOnException is not supported in Pages Functions');
    }
  };

  // Delegate to the main request handler
  return handleRequest(request, env, ctx);
}

function createConfig(env = {}) {
  return {
    TIMEOUT_SECONDS: parseInt(String(env.TIMEOUT_SECONDS), 10) || 30,
    MAX_RETRIES: parseInt(String(env.MAX_RETRIES), 10) || 3,
    RETRY_DELAY_MS: parseInt(String(env.RETRY_DELAY_MS), 10) || 1000,
    CACHE_DURATION: parseInt(String(env.CACHE_DURATION), 10) || 1800, // 30 minutes
    SECURITY: {
      ALLOWED_METHODS:
        typeof env.ALLOWED_METHODS === 'string' ? env.ALLOWED_METHODS.split(',') : ['GET', 'HEAD'],
      ALLOWED_ORIGINS:
        typeof env.ALLOWED_ORIGINS === 'string' ? env.ALLOWED_ORIGINS.split(',') : ['*'],
      MAX_PATH_LENGTH: parseInt(String(env.MAX_PATH_LENGTH), 10) || 2048
    },
    PLATFORMS
  };
}

function addSecurityHeaders(headers) {
  headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
  headers.set('X-Frame-Options', 'DENY');
  headers.set('X-XSS-Protection', '1; mode=block');
  headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
  headers.set('Content-Security-Policy', "default-src 'none'; img-src 'self'; script-src 'none'");
  headers.set('Permissions-Policy', 'interest-cohort=()');
  return headers;
}

function createSnapLogger(prefix = '[snapDOM]', { ttlMs = 5 * 60_000, maxEntries = 12 } = {}) {
  const seen = new Map()
  let emitted = 0

  function log(level, key, msg) {
    if (emitted >= maxEntries) return
    const now = Date.now()
    const until = seen.get(key) || 0
    if (until > now) return // still under TTL
    seen.set(key, now + ttlMs)
    emitted++
    if (level === 'warn' && console && console.warn) console.warn(`${prefix} ${msg}`)
    else if (console && console.error) console.error(`${prefix} ${msg}`)
  }

  return {
    warnOnce(key, msg) { log('warn', key, msg) },
    errorOnce(key, msg) { log('error', key, msg) },
    reset() { seen.clear(); emitted = 0 },
  }
}

function isSpecialURL(url) {
  return /^data:|^blob:|^about:blank$/i.test(url)
}

function isAlreadyProxied(url, useProxy) {
  try {
    const baseHref = (typeof location !== 'undefined' && location.href) ? location.href : 'http://localhost/'
    const proxyBaseRaw = useProxy.includes('{url}') ? useProxy.split('{url}')[0] : useProxy
    const proxyBase = new URL(proxyBaseRaw || '.', baseHref)
    const u = new URL(url, baseHref)

    // Same origin as proxy → likely already proxied
    if (u.origin === proxyBase.origin) return true

    // Common query keys used by proxies
    const sp = u.searchParams
    if (sp && (sp.has('url') || sp.has('target'))) return true
  } catch {}
  return false
}

function shouldProxy(url, useProxy) {
  if (!useProxy) return false
  if (isSpecialURL(url)) return false
  if (isAlreadyProxied(url, useProxy)) return false
  try {
    const base = (typeof location !== 'undefined' && location.href) ? location.href : 'http://localhost/'
    const u = new URL(url, base)
    return (typeof location !== 'undefined') ? (u.origin !== location.origin) : true
  } catch {
    // If URL can't be parsed but a proxy is configured, err on the side of proxying
    return !!useProxy
  }
}

function applyProxy(url, useProxy) {
  if (!useProxy) return url

  // Template tokens
  if (useProxy.includes('{url}')) {
    return useProxy
      .replace('{urlRaw}', safeEncodeURI(url))     // path-style (1.9.9 compatible)
      .replace('{url}', encodeURIComponent(url))  // query-style
  }

  // Explicit query base
  if (/[?&]url=?$/.test(useProxy)) {
    return `${useProxy}${encodeURIComponent(url)}`
  }
  // Ends with '?' → tests want '?url=' prefix
  if (useProxy.endsWith('?')) {
    return `${useProxy}url=${encodeURIComponent(url)}`
  }

  // Path-style base
  if (useProxy.endsWith('/')) {
    return `${useProxy}${safeEncodeURI(url)}`     // DO NOT use encodeURIComponent here
  }

  // Fallback query param
  const sep = useProxy.includes('?') ? '&' : '?'
  return `${useProxy}${sep}url=${encodeURIComponent(url)}`
}

function blobToDataURL(blob) {
  return new Promise((res, rej) => {
    const fr = new FileReader()
    fr.onload = () => res(String(fr.result || ''))
    fr.onerror = () => rej(new Error('read_failed'))
    fr.readAsDataURL(blob)
  })
}

function makeKey(url, o) {
  return [
    o.as || 'blob',
    o.timeout ?? 3000,
    o.useProxy || '',
    o.errorTTL ?? 8000,
    url
  ].join('|')
}

async function snapFetch(url, options = {}) {
  const as = options.as ?? 'blob'
  const timeout = options.timeout ?? 3000
  const useProxy = options.useProxy || ''
  const errorTTL = options.errorTTL ?? 8000
  const headers = options.headers || {}
  const silent = !!options.silent

  // --- Special schemes: handle explicitly so tests expect data: outputs ---

  // data:
  if (/^data:/i.test(url)) {
    try {
      if (as === 'text') {
        return { ok: true, data: String(url), status: 200, url, fromCache: false }
      }
      if (as === 'dataURL') {
        return {
          ok: true,
          data: String(url),
          status: 200,
          url,
          fromCache: false,
          mime: String(url).slice(5).split(';')[0] || ''
        }
      }
      // as === 'blob' → decode data: to Blob
      const [, meta = '', data = ''] = String(url).match(/^data:([^,]*),(.*)$/) || []
      const isBase64 = /;base64/i.test(meta)
      const bin = isBase64 ? atob(data) : decodeURIComponent(data)
      const bytes = new Uint8Array([...bin].map(c => c.charCodeAt(0)))
      const b = new Blob([bytes], { type: (meta || '').split(';')[0] || '' })
      return { ok: true, data: b, status: 200, url, fromCache: false, mime: b.type || '' }
    } catch {
      return { ok: false, data: null, status: 0, url, fromCache: false, reason: 'special_url_error' }
    }
  }

  // blob:
  if (/^blob:/i.test(url)) {
    try {
      const resp = await fetch(url)
      if (!resp.ok) {
        return { ok: false, data: null, status: resp.status, url, fromCache: false, reason: 'http_error' }
      }
      const blob = await resp.blob()
      const mime = blob.type || resp.headers.get('content-type') || ''
      if (as === 'dataURL') {
        const dataURL = await blobToDataURL(blob)
        return { ok: true, data: dataURL, status: resp.status, url, fromCache: false, mime }
      }
      if (as === 'text') {
        const text = await blob.text()
        return { ok: true, data: text, status: resp.status, url, fromCache: false, mime }
      }
      return { ok: true, data: blob, status: resp.status, url, fromCache: false, mime }
    } catch {
      // Do NOT memoize blob: failures — these are often transient (revocations)
      return { ok: false, data: null, status: 0, url, fromCache: false, reason: 'network' }
    }
  }

  // about:blank
  if (/^about:blank$/i.test(url)) {
    if (as === 'dataURL') {
      return {
        ok: true,
        data: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR4nGMAAQAABQABDQottAAAAABJRU5ErkJggg==',
        status: 200,
        url,
        fromCache: false,
        mime: 'image/png'
      }
    }
    return { ok: true, data: as === 'text' ? '' : new Blob([]), status: 200, url, fromCache: false }
  }

  // ---- Normal http(s) path ----

  const key = makeKey(url, { as, timeout, useProxy, errorTTL })

  // Error cache
  const e = _errorCache.get(key)
  if (e && e.until > Date.now()) {
    return { ...e.result, fromCache: true }
  } else if (e) {
    _errorCache.delete(key)
  }

  // Inflight dedupe
  const inflight = _inflight.get(key)
  if (inflight) return inflight

  // Final URL (with robust proxying) & credentials
  const finalURL = shouldProxy(url, useProxy) ? applyProxy(url, useProxy) : url

  let cred = options.credentials
  if (!cred) {
    try {
      const base = (typeof location !== 'undefined' && location.href) ? location.href : 'http://localhost/'
      const u = new URL(url, base)
      const sameOrigin = (typeof location !== 'undefined') && (u.origin === location.origin)
      cred = sameOrigin ? 'include' : 'omit'
    } catch {
      cred = 'omit'
    }
  }

  // Timeout controller
  const ctrl = new AbortController()
  const timer = setTimeout(() => ctrl.abort('timeout'), timeout)

  const p = (async () => {
    try {
      const resp = await fetch(finalURL, { signal: ctrl.signal, credentials: cred, headers })

      if (!resp.ok) {
        const result = { ok: false, data: null, status: resp.status, url: finalURL, fromCache: false, reason: 'http_error' }
        if (errorTTL > 0) _errorCache.set(key, { until: Date.now() + errorTTL, result })
        if (!silent) {
          const short = `${resp.status} ${resp.statusText || ''}`.trim()
          snapLogger.warnOnce(
            `http:${resp.status}:${as}:${(new URL(url, (location?.href ?? 'http://localhost/'))).origin}`,
            `HTTP error ${short} while fetching ${as} ${url}`
          )
        }
        options.onError && options.onError(result)
        return result
      }

      if (as === 'text') {
        const text = await resp.text()
        return { ok: true, data: text, status: resp.status, url: finalURL, fromCache: false }
      }

      const blob = await resp.blob()
      const mime = blob.type || resp.headers.get('content-type') || ''

      if (as === 'dataURL') {
        const dataURL = await blobToDataURL(blob)
        return { ok: true, data: dataURL, status: resp.status, url: finalURL, fromCache: false, mime }
      }

      // default 'blob'
      return { ok: true, data: blob, status: resp.status, url: finalURL, fromCache: false, mime }

    } catch (err) {
      const reason =
        (err && typeof err === 'object' && 'name' in err && err.name === 'AbortError')
          ? (String(err.message || '').includes('timeout') ? 'timeout' : 'abort')
          : 'network'

      const result = { ok: false, data: null, status: 0, url: finalURL, fromCache: false, reason }

      // Persist HTTP network failures; avoid memoizing non-HTTP (handled above)
      if (!/^blob:/i.test(url) && errorTTL > 0) {
        _errorCache.set(key, { until: Date.now() + errorTTL, result })
      }

      if (!silent) {
        const k = `${reason}:${as}:${(new URL(url, (location?.href ?? 'http://localhost/'))).origin}`
        const tips = reason === 'timeout'
          ? `Timeout after ${timeout}ms. Consider increasing timeout or using a proxy for ${url}`
          : reason === 'abort'
            ? `Request aborted while fetching ${as} ${url}`
            : `Network/CORS issue while fetching ${as} ${url}. A proxy may be required`
        snapLogger.errorOnce(k, tips)
      }

      options.onError && options.onError(result)
      return result

    } finally {
      clearTimeout(timer)
      _inflight.delete(key)
    }
  })()

  _inflight.set(key, p)
  return p
}

function normalizePlugin(spec) {
  if (!spec) return null
  if (Array.isArray(spec)) {
    const [factory, options] = spec
    return typeof factory === 'function' ? factory(options) : factory
  }
  if (typeof spec === 'object' && 'plugin' in spec) {
    const { plugin, options } = spec
    return typeof plugin === 'function' ? plugin(options) : plugin
  }
  if (typeof spec === 'function') return spec()
  return spec
}

function registerPlugins(...defs) {
  const flat = defs.flat()
  for (const d of flat) {
    const inst = normalizePlugin(d)
    if (!inst) continue
    // 🔒 de-dup por name
    if (!__plugins.some(p => p && p.name && inst.name && p.name === inst.name)) {
      __plugins.push(inst)
    }
  }
}

