                      sessionId: capturedSessionId,
                      model: response.model,
                      cwd: response.cwd
                    });
                  }
                }

                // Send system info to frontend
                ws.send({
                  type: 'cursor-system',
                  data: response,
                  sessionId: capturedSessionId || sessionId || null
                });
              }
              break;

            case 'user':
              // Forward user message
              ws.send({
                type: 'cursor-user',
                data: response,
                sessionId: capturedSessionId || sessionId || null
              });
              break;

            case 'assistant':
              // Accumulate assistant message chunks
              if (response.message && response.message.content && response.message.content.length > 0) {
                const textContent = response.message.content[0].text;
                messageBuffer += textContent;

                // Send as Claude-compatible format for frontend
                ws.send({
                  type: 'claude-response',
                  data: {
                    type: 'content_block_delta',
                    delta: {
                      type: 'text_delta',
                      text: textContent
                    }
                  },
                  sessionId: capturedSessionId || sessionId || null
                });
              }
              break;

            case 'result':
              // Session complete
              console.log('Cursor session result:', response);

              // Send final message if we have buffered content
              if (messageBuffer) {
                ws.send({
                  type: 'claude-response',
                  data: {
                    type: 'content_block_stop'
                  },
                  sessionId: capturedSessionId || sessionId || null
                });
              }

              // Send completion event
              ws.send({
                type: 'cursor-result',
                sessionId: capturedSessionId || sessionId,
                data: response,
                success: response.subtype === 'success'
              });
              break;

            default:
              // Forward any other message types
              ws.send({
                type: 'cursor-response',
                data: response,
                sessionId: capturedSessionId || sessionId || null
              });
          }
        } catch (parseError) {
          console.log('📄 Non-JSON response:', line);
          // If not JSON, send as raw text
          ws.send({
            type: 'cursor-output',
            data: line,
            sessionId: capturedSessionId || sessionId || null
          });
        }
      }
    });

    // Handle stderr
    cursorProcess.stderr.on('data', (data) => {
      console.error('Cursor CLI stderr:', data.toString());
      ws.send({
        type: 'cursor-error',
        error: data.toString(),
        sessionId: capturedSessionId || sessionId || null
      });
    });

    // Handle process completion
    cursorProcess.on('close', async (code) => {
      console.log(`Cursor CLI process exited with code ${code}`);

      // Clean up process reference
      const finalSessionId = capturedSessionId || sessionId || processKey;
      activeCursorProcesses.delete(finalSessionId);

      ws.send({
        type: 'claude-complete',
        sessionId: finalSessionId,
        exitCode: code,
        isNewSession: !sessionId && !!command // Flag to indicate this was a new session
      });

      if (code === 0) {
        resolve();
      } else {
        reject(new Error(`Cursor CLI exited with code ${code}`));
      }
    });

    // Handle process errors
    cursorProcess.on('error', (error) => {
      console.error('Cursor CLI process error:', error);

      // Clean up process reference on error
      const finalSessionId = capturedSessionId || sessionId || processKey;
      activeCursorProcesses.delete(finalSessionId);

      ws.send({
        type: 'cursor-error',
        error: error.message,
        sessionId: capturedSessionId || sessionId || null
      });

      reject(error);
    });

    // Close stdin since Cursor doesn't need interactive input
    cursorProcess.stdin.end();
  });
}

function abortCursorSession(sessionId) {
  const process = activeCursorProcesses.get(sessionId);
  if (process) {
    console.log(`🛑 Aborting Cursor session: ${sessionId}`);
    process.kill('SIGTERM');
    activeCursorProcesses.delete(sessionId);
    return true;
  }
  return false;
}

function isCursorSessionActive(sessionId) {
  return activeCursorProcesses.has(sessionId);
}

function getActiveCursorSessions() {
  return Array.from(activeCursorProcesses.keys());
}

function transformCodexEvent(event) {
  // Map SDK event types to a consistent format
  switch (event.type) {
    case 'item.started':
    case 'item.updated':
    case 'item.completed':
      const item = event.item;
      if (!item) {
        return { type: event.type, item: null };
      }

      // Transform based on item type
      switch (item.type) {
        case 'agent_message':
          return {
            type: 'item',
            itemType: 'agent_message',
            message: {
              role: 'assistant',
              content: item.text
            }
          };

        case 'reasoning':
          return {
            type: 'item',
            itemType: 'reasoning',
            message: {
              role: 'assistant',
              content: item.text,
              isReasoning: true
            }
          };

        case 'command_execution':
          return {
            type: 'item',
            itemType: 'command_execution',
            command: item.command,
            output: item.aggregated_output,
            exitCode: item.exit_code,
            status: item.status
          };

        case 'file_change':
          return {
            type: 'item',
            itemType: 'file_change',
            changes: item.changes,
            status: item.status
          };

        case 'mcp_tool_call':
          return {
            type: 'item',
            itemType: 'mcp_tool_call',
            server: item.server,
            tool: item.tool,
            arguments: item.arguments,
            result: item.result,
            error: item.error,
            status: item.status
          };

        case 'web_search':
          return {
            type: 'item',
            itemType: 'web_search',
            query: item.query
          };

        case 'todo_list':
          return {
            type: 'item',
            itemType: 'todo_list',
            items: item.items
          };

        case 'error':
          return {
            type: 'item',
            itemType: 'error',
            message: {
              role: 'error',
              content: item.message
            }
          };

        default:
          return {
            type: 'item',
            itemType: item.type,
            item: item
          };
      }

    case 'turn.started':
      return {
        type: 'turn_started'
      };

    case 'turn.completed':
      return {
        type: 'turn_complete',
        usage: event.usage
      };

    case 'turn.failed':
      return {
        type: 'turn_failed',
        error: event.error
      };

    case 'thread.started':
      return {
        type: 'thread_started',
        threadId: event.id
      };

    case 'error':
      return {
        type: 'error',
        message: event.message
      };

    default:
      return {
        type: event.type,
        data: event
      };
  }
}

function mapPermissionModeToCodexOptions(permissionMode) {
  switch (permissionMode) {
    case 'acceptEdits':
      return {
        sandboxMode: 'workspace-write',
        approvalPolicy: 'never'
      };
    case 'bypassPermissions':
      return {
        sandboxMode: 'danger-full-access',
        approvalPolicy: 'never'
      };
    case 'default':
    default:
      return {
        sandboxMode: 'workspace-write',
        approvalPolicy: 'untrusted'
      };
  }
}

async function queryCodex(command, options = {}, ws) {
  const {
    sessionId,
    cwd,
    projectPath,
    model,
    permissionMode = 'default'
  } = options;

  const workingDirectory = cwd || projectPath || process.cwd();
  const { sandboxMode, approvalPolicy } = mapPermissionModeToCodexOptions(permissionMode);

  let codex;
  let thread;
  let currentSessionId = sessionId;

  try {
    // Initialize Codex SDK
    codex = new Codex();

    // Thread options with sandbox and approval settings
    const threadOptions = {
      workingDirectory,
      skipGitRepoCheck: true,
      sandboxMode,
      approvalPolicy,
      model
    };

    // Start or resume thread
    if (sessionId) {
      thread = codex.resumeThread(sessionId, threadOptions);
    } else {
      thread = codex.startThread(threadOptions);
    }

    // Get the thread ID
    currentSessionId = thread.id || sessionId || `codex-${Date.now()}`;

    // Track the session
    activeCodexSessions.set(currentSessionId, {
      thread,
      codex,
      status: 'running',
      startedAt: new Date().toISOString()
    });

    // Send session created event
    sendMessage(ws, {
      type: 'session-created',
      sessionId: currentSessionId,
      provider: 'codex'
    });

    // Execute with streaming
    const streamedTurn = await thread.runStreamed(command);

    for await (const event of streamedTurn.events) {
      // Check if session was aborted
      const session = activeCodexSessions.get(currentSessionId);
      if (!session || session.status === 'aborted') {
        break;
      }

      if (event.type === 'item.started' || event.type === 'item.updated') {
        continue;
      }

      const transformed = transformCodexEvent(event);

      sendMessage(ws, {
        type: 'codex-response',
        data: transformed,
        sessionId: currentSessionId
      });

      // Extract and send token usage if available (normalized to match Claude format)
      if (event.type === 'turn.completed' && event.usage) {
        const totalTokens = (event.usage.input_tokens || 0) + (event.usage.output_tokens || 0);
        sendMessage(ws, {
          type: 'token-budget',
          data: {
            used: totalTokens,
            total: 200000 // Default context window for Codex models
          },
          sessionId: currentSessionId
        });
      }
    }

    // Send completion event
    sendMessage(ws, {
      type: 'codex-complete',
      sessionId: currentSessionId,
      actualSessionId: thread.id
    });

  } catch (error) {
    console.error('[Codex] Error:', error);

    sendMessage(ws, {
      type: 'codex-error',
      error: error.message,
      sessionId: currentSessionId
    });

  } finally {
    // Update session status
    if (currentSessionId) {
      const session = activeCodexSessions.get(currentSessionId);
      if (session) {
        session.status = 'completed';
      }
    }
  }
}

function abortCodexSession(sessionId) {
  const session = activeCodexSessions.get(sessionId);

  if (!session) {
    return false;
  }

  session.status = 'aborted';

  // The SDK doesn't have a direct abort method, but marking status
  // will cause the streaming loop to exit

  return true;
}

function isCodexSessionActive(sessionId) {
  const session = activeCodexSessions.get(sessionId);
  return session?.status === 'running';
}

function getActiveCodexSessions() {
  const sessions = [];

  for (const [id, session] of activeCodexSessions.entries()) {
    if (session.status === 'running') {
      sessions.push({
        id,
        status: session.status,
        startedAt: session.startedAt
      });
    }
  }

  return sessions;
}

function countMarkdownFiles(dirPath) {
  let count = 0;

  try {
    const files = fs.readdirSync(dirPath);

    for (const file of files) {
      const filePath = path.join(dirPath, file);
      const stat = fs.statSync(filePath);

      if (stat.isDirectory()) {
        count += countMarkdownFiles(filePath); // 递归子目录
      } else if (path.extname(file) === ".md") {
        count++;
      }
    }
  } catch (error) {
    console.error(`读取目录出错: ${error.message}`);
  }

  return count;
}

function generateSidebarConfig(dirPath) {
  // 将相对路径转为绝对路径
  const absolutePath = path.resolve(process.cwd(), dirPath);
  // 创建一个数组，存储 侧边栏目录列表
  let sidebarItems = [];
  // 如果根目录存在 README.md ,添加空字符串
  if (fs.existsSync(path.join(absolutePath, "README.md"))) {
    sidebarItems.push("");
  }

  /**
   * 递归的处理目录
   * @param {*} currentPath 当前的目录
   * @param {*} relativePath  当前目录的相对路径
   * @param {*} config  当前的配置
   */
  function processDirectory(currentPath, relativePath = "", config = sidebarItems) {
    // 获取目录下的所有文件
    const items = fs.readdirSync(currentPath, { withFileTypes: true });
    // 文件列表
    const files = [];
    // 目录列表
    const directories = [];
    // 遍历 items 得到所有的文件和目录
    items.forEach((item) => {
      if (item.isDirectory() && !item.name.startsWith(".")) {
        directories.push(item);
      } else if (item.isFile() && item.name.endsWith(".md") && item.name !== "README.md") {
        files.push(item);
      }
    });
    // 处理文件
    if (files.length > 0) {
      // 创建包含文件路径和创建时间的对象数组
      const fileInfos = files.map((file) => {
        const fullPath = path.join(currentPath, file.name);
        const filePath = relativePath
          ? `${relativePath}/${file.name.replace(".md", "")}`
          : file.name.replace(".md", "");
        const stats = fs.statSync(fullPath);
        return {
          path: filePath,
          birthtime: stats.birthtime,
        };
      });

      // 按创建时间降序排序，最新的文件排在前面
      fileInfos
        .sort((a, b) => b.birthtime.getTime() - a.birthtime.getTime())
        .forEach((fileInfo) => {
          if (fileInfo.path.includes("🔥DeepSeek 小白快速上手指南")) {
            config.unshift(fileInfo.path); // 将该文件放在最前面
          } else {
            config.push(fileInfo.path);
          }
        });
    }
    if (directories.length > 0) {
      // 创建包含目录信息和创建时间的对象数组
      const dirInfos = directories.map((dir) => {
        const subDirectoryPath = path.join(currentPath, dir.name);
        const stats = fs.statSync(subDirectoryPath);
        return {
          dir: dir,
          birthtime: stats.birthtime,
        };
      });

      // 按创建时间降序排序，最新的目录排在前面
      dirInfos.sort((a, b) => b.birthtime.getTime() - a.birthtime.getTime());

      // 处理排序后的目录
      dirInfos.forEach((dirInfo) => {
        const dir = dirInfo.dir;
        const subDirectoryPath = path.join(currentPath, dir.name);
        const newRelativePath = relativePath ? `${relativePath}/${dir.name}` : dir.name;

        // 查找当前目录是否已经存在于配置中
        let existingDir = config.find((item) => item.title === dir.name);
        if (!existingDir) {
          existingDir = {
            title: dir.name,
            collapsable: true,
            children: [],
          };
          config.push(existingDir);
        }

        processDirectory(subDirectoryPath, newRelativePath, existingDir.children); // 传递 existingDir.children 作为 config
      });
    }
  }
  processDirectory(absolutePath);
  // 返回计算得到的 sidebar 数组
  return sidebarItems;
}

function genReadme(directory) {
  if (!fs.existsSync(directory)) {
    console.error(`错误：目录 "${directory}" 不存在`);
    process.exit(1);
  }

  const dirName = path.basename(directory);
  const readmeContent = generateContent(directory, dirName);
  const readmePath = path.join(directory, "README.md");

  // 写入 README.md 文件
  fs.writeFileSync(readmePath, readmeContent);
  console.log(`README.md 文件已生成在 ${readmePath}，⚠️注意检查是否有问题！`);
}

function generateContent(directory, dirName) {
  let content = `# ${dirName}\n\n`;
  content += `> 你全面的 AI 知识库，一网打尽最新 AI 资讯，都在 [https://ai.codefather.cn](https://ai.codefather.cn)\n\n`;

  // 获取所有一级子目录并按创建时间排序，最新的放在前面
  const subDirs = getSubDirectories(directory).sort((a, b) => {
    const statA = fs.statSync(a);
    const statB = fs.statSync(b);
    return statB.birthtime.getTime() - statA.birthtime.getTime();
  });

  if (subDirs.length > 0) {
    // 循环处理每个一级子目录
    for (const subDir of subDirs) {
      const subDirName = path.basename(subDir);

      content += `## ${subDirName}\n\n`;

      // 递归获取子目录下的所有 Markdown 文件
      const subDirFiles = getFilesInDirectory(subDir).sort((a, b) => {
        // First check for DeepSeek guide
        const nameA = path.basename(a);
        const nameB = path.basename(b);
        if (nameA.includes("🔥DeepSeek 小白快速上手指南")) return -1;
        if (nameB.includes("🔥DeepSeek 小白快速上手指南")) return 1;

        // Then sort by date for other files
        const statA = fs.statSync(a);
        const statB = fs.statSync(b);
        return statB.birthtime.getTime() - statA.birthtime.getTime();
      });

      for (let i = 0; i < Math.min(subDirFiles.length, 100); i++) {
        const file = subDirFiles[i];

        // 跳过 README.md 文件
        if (path.basename(file).toLowerCase() === "readme.md") {
          continue;
        }

        const relativePath = path.relative(directory, file)?.replaceAll(" ", "%20");
        content += `[${path.basename(file, ".md")}](${relativePath})\n\n`;
      }
    }
  } else {
    // 如果没有子目录，直接处理当前目录下的 Markdown 文件
    const files = getFilesInDirectory(directory).sort((a, b) => {
      const statA = fs.statSync(a);
      const statB = fs.statSync(b);
      return statB.birthtime.getTime() - statA.birthtime.getTime();
    });

    for (let i = 0; i < Math.min(files.length, 100); i++) {
      const file = files[i];
      if (path.basename(file).toLowerCase() === "readme.md") continue;
      const relativePath = path.basename(file)?.replaceAll(" ", "%20");
      content += `[${path.basename(file, ".md")}](${relativePath})\n\n`;
    }
  }
  if (subDirs.length > 0) {
    // 添加底部内容
    content += `> 你全面的 AI 知识库，一网打尽最新 AI 资讯，都在 [https://ai.codefather.cn](https://ai.codefather.cn)\n\n`;
  }

  return content;
}

function getSubDirectories(directory) {
  const items = fs.readdirSync(directory, { withFileTypes: true });
  return items.filter((item) => item.isDirectory()).map((dir) => path.join(directory, dir.name));
}

function getFilesInDirectory(directory) {
  const items = fs.readdirSync(directory, { withFileTypes: true });
  let files = [];

  for (const item of items) {
    const fullPath = path.join(directory, item.name);
    if (item.isDirectory()) {
      // 递归获取子目录中的文件
      files = files.concat(getFilesInDirectory(fullPath));
    } else if (item.isFile() && path.extname(item.name) === ".md") {
      files.push(fullPath);
    }
  }

  return files;
}

function formatMdContent(content, filePath) {
  // 检查内容是否以一级或二级标题开始
  const firstLine = content.trim().split("")[0];
  const hasTitle = /^#\s|^##\s/.test(firstLine);
  // 获取文件名（不含扩展名）
  const fileName = path.basename(filePath, path.extname(filePath));

  if (!hasTitle) {
    // 如果没有标题，添加二级标题
    return `## ${fileName}\n\n${content}`;
  } else {
    // 如果有标题，检查标题内容是否与文件名一致
    const titleContent = firstLine.replace(/^#\s|^##\s/, "").trim();
    if (titleContent !== fileName) {
      // 如果标题内容与文件名不一致，在开头添加文件名作为二级标题
      return `## ${fileName}\n\n${content}`;
    }
  }

  return content;
}

function processDirectory(dirPath) {
  // 获取绝对路径
  const absolutePath = path.resolve(process.cwd(), dirPath);

  // 读取目录下的所有文件
  const files = fs.readdirSync(absolutePath);

  files.forEach((file) => {
    const filePath = path.join(absolutePath, file);
    const stat = fs.statSync(filePath);

    if (stat.isFile() && path.extname(file) === ".md") {
      // 读取并处理 markdown 文件
      const content = fs.readFileSync(filePath, "utf8");
      const formattedContent = formatMdContent(content, filePath);

      // 写回文件
      fs.writeFileSync(filePath, formattedContent, "utf8");
      console.log(`已处理: ${file}`);
    } else if (stat.isDirectory()) {
      // 递归处理子目录
      processDirectory(filePath);
    }
  });
}

function normalize (path) {
  return decodeURI(path)
    .replace(hashRE, '')
    .replace(extRE, '')
}

function getHash (path) {
  const match = path.match(hashRE)
  if (match) {
    return match[0]
  }
}

function isSentenceTerminator(c, includeNewlines = true) {
  return ".!?…。？！".includes(c) || (includeNewlines && c === "\n");
}

function isTrailingChar(c) {
  return "\"')]}」』".includes(c);
}

function getTokenFromBuffer(buffer, start) {
  let end = start;
  while (end < buffer.length && !/\s/.test(buffer[end])) {
    ++end;
  }
  return buffer.substring(start, end);
}

function isAbbreviation(token) {
  // Remove possessive endings and trailing periods.
  token = token.replace(/['’]s$/i, "").replace(/\.+$/, "");
  return ABBREVIATIONS.has(token.toLowerCase());
}

function updateStack(c, stack, i, buffer) {
  // Handle standard quotes.
  if (c === '"' || c === "'") {
    // Ignore an apostrophe if it's between letters (e.g., in contractions).
    if (c === "'" && i > 0 && i < buffer.length - 1 && /[A-Za-z]/.test(buffer[i - 1]) && /[A-Za-z]/.test(buffer[i + 1])) {
      return;
    }
    if (stack.length && stack.at(-1) === c) {
      stack.pop();
    } else {
      stack.push(c);
    }
    return;
  }
  // Handle opening punctuation.
  if (OPENING.has(c)) {
    stack.push(c);
    return;
  }
  // Handle closing punctuation.
  const expectedOpening = MATCHING.get(c);
  if (expectedOpening && stack.length && stack.at(-1) === expectedOpening) {
    stack.pop();
  }
}

_resolve() {
    if (this._resolver) {
      this._resolver();
      this._resolver = null;
    }
  }

_process() {
    let sentenceStart = 0;
    const buffer = this._buffer;
    const len = buffer.length;
    let i = 0;
    let stack = [];

    // Helper to scan from the current index over trailing terminators and punctuation.
    const scanBoundary = (idx) => {
      let end = idx;
      // Consume contiguous sentence terminators (excluding newlines).
      while (end + 1 < len && isSentenceTerminator(buffer[end + 1], false)) {
        ++end;
      }
      // Consume trailing characters (e.g., closing quotes/brackets).
      while (end + 1 < len && isTrailingChar(buffer[end + 1])) {
        ++end;
      }
      let nextNonSpace = end + 1;
      while (nextNonSpace < len && /\s/.test(buffer[nextNonSpace])) {
        ++nextNonSpace;
      }
      return { end, nextNonSpace };
    };

    while (i < len) {
      const c = buffer[i];
      updateStack(c, stack, i, buffer);

      // Only consider splitting if we're not inside any nested structure.
      if (stack.length === 0 && isSentenceTerminator(c)) {
        const currentSegment = buffer.slice(sentenceStart, i);
        // Skip splitting for likely numbered lists (e.g., "1." or "\n2.").
        if (/(^|\n)\d+$/.test(currentSegment)) {
          ++i;
          continue;
        }

        const { end: boundaryEnd, nextNonSpace } = scanBoundary(i);

        // If the terminator is not a newline and there's no extra whitespace,
        // we might be in the middle of a token (e.g., "$9.99"), so skip splitting.
        if (i === nextNonSpace - 1 && c !== "\n") {
          ++i;
          continue;
        }

        // Wait for more text if there's no non-whitespace character yet.
        if (nextNonSpace === len) {
          break;
        }

        // Determine the token immediately preceding the terminator.
        let tokenStart = i - 1;
        while (tokenStart >= 0 && /\S/.test(buffer[tokenStart])) {
          tokenStart--;
        }
        tokenStart = Math.max(sentenceStart, tokenStart + 1);
