function transcriber(mutationsList, observer) {
  mutationsList.forEach((mutation) => {
    try {
      // Check for new speaker divs
      mutation.addedNodes.forEach((node) => {
        if (
          node.nodeType === Node.ELEMENT_NODE &&
          node.classList.contains("nMcdL")
        ) {
          const speakerId = Date.now(); // Unique ID for this speaker instance
          const speakerName = node.querySelector(".KcIKyf").textContent.trim();
          const captionsDiv = node.querySelector(".bh44bd");

          // Initialize buffer for this speaker
          activeSpeakerBuffers.set(speakerId, {
            name: speakerName,
            startTime: new Date()
              .toLocaleString("default", timeFormat)
              .toUpperCase(),
            text: captionsDiv.textContent.trim(),
          });

          // Create observer for this speaker's captions
          const captionsObserver = new MutationObserver((captionsMutations) => {
            const speakerBuffer = activeSpeakerBuffers.get(speakerId);
            if (speakerBuffer) {
              speakerBuffer.text = captionsDiv.textContent.trim();

              // If caption length is too long, process it
              if (speakerBuffer.text.length > 250) {
                processSpeakerTranscript(speakerId);
              }
            }
          });

          // Start observing this speaker's captions
          captionsObserver.observe(captionsDiv, {
            childList: true,
            characterData: true,
            subtree: true,
          });

          speakerObservers.set(speakerId, captionsObserver);

          // Set timeout to process this speaker's transcript if they stop talking
          setTimeout(() => {
            processSpeakerTranscript(speakerId);
          }, 5000);
        }
      });

      // Check for removed speaker divs
      mutation.removedNodes.forEach((node) => {
        if (
          node.nodeType === Node.ELEMENT_NODE &&
          node.classList.contains("nMcdL")
        ) {
          // Process any remaining transcripts for removed speakers
          speakerObservers.forEach((observer, speakerId) => {
            processSpeakerTranscript(speakerId);
          });
        }
      });
    } catch (error) {
      if (!isTranscriptDomErrorCaptured && !hasMeetingEnded) {
        console.error("Transcript observer error:", error);
        chrome.storage.local.set({ meetingQA: [] });
        showNotification(extensionStatusJSON_bug);
        isTranscriptDomErrorCaptured = true;
      }
    }
  });
}

function processSpeakerTranscript(speakerId) {
  const speakerBuffer = activeSpeakerBuffers.get(speakerId);
  if (speakerBuffer && speakerBuffer.text.trim()) {
    // Push to transcript array
    transcript.push({
      personName: speakerBuffer.name,
      timeStamp: speakerBuffer.startTime,
      personTranscript: speakerBuffer.text,
    });

    // Save to storage
    overWriteChromeStorage(["transcript"], false);

    // Send via WebSocket if connected
    if (ws && ws.readyState === WebSocket.OPEN) {
      const formattedPayload = `${speakerBuffer.name} (${speakerBuffer.startTime})\n${speakerBuffer.text}\n`;
      ws.send(
        JSON.stringify({
          type: "transcript_update",
          data: formattedPayload,
        })
      );
    }

    // Cleanup
    const observer = speakerObservers.get(speakerId);
    if (observer) {
      observer.disconnect();
      speakerObservers.delete(speakerId);
    }
    console.log("activeSpeakerBuffers", activeSpeakerBuffers);
    activeSpeakerBuffers.delete(speakerId);
  }
}

async function callLLM(config, messages, onChunk) {
  const { type, baseUrl, apiKey, model } = config;

  if (type === 'openai') {
    return callOpenAI(baseUrl, apiKey, model, messages, onChunk);
  } else if (type === 'anthropic') {
    return callAnthropic(baseUrl, apiKey, model, messages, onChunk);
  } else {
    throw new Error(`Unsupported provider type: ${type}`);
  }
}

async function callOpenAI(baseUrl, apiKey, model, messages, onChunk) {
  const url = `${baseUrl}/chat/completions`;

  // Process messages to support multimodal content (text + images)
  const processedMessages = messages.map(processMessageForOpenAI);

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model,
      messages: processedMessages,
      stream: true,
      // max_tokens: 64000,
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`OpenAI API error: ${response.status} ${error}`);
  }

  return processOpenAIStream(response.body, onChunk);
}

async function processOpenAIStream(body, onChunk) {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let fullText = '';
  let buffer = '';

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed || trimmed === 'data: [DONE]') continue;

        if (trimmed.startsWith('data: ')) {
          try {
            const json = JSON.parse(trimmed.slice(6));
            const content = json.choices?.[0]?.delta?.content;
            if (content) {
              fullText += content;
              if (onChunk) onChunk(content);
            }
          } catch (e) {
            console.error('Failed to parse SSE:', e);
          }
        }
      }
    }
  } finally {
    reader.releaseLock();
  }

  return fullText;
}

async function callAnthropic(baseUrl, apiKey, model, messages, onChunk) {
  const url = `${baseUrl}/messages`;

  // Convert messages format for Anthropic with multimodal support
  const systemMessage = messages.find(m => m.role === 'system');
  const chatMessages = messages.filter(m => m.role !== 'system');
  const processedMessages = chatMessages.map(processMessageForAnthropic);

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': apiKey,
    },
    body: JSON.stringify({
      model,
      messages: processedMessages,
      system: systemMessage ? [{ type: 'text', text: systemMessage.content }] : undefined,
      max_tokens: 64000,
      stream: true,
      temperature: 1,
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Anthropic API error: ${response.status} ${error}`);
  }

  return processAnthropicStream(response.body, onChunk);
}

async function processAnthropicStream(body, onChunk) {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let fullText = '';
  let buffer = '';

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed || !trimmed.startsWith('data: ')) continue;

        try {
          const json = JSON.parse(trimmed.slice(6));

          if (json.type === 'content_block_delta') {
            const content = json.delta?.text;
            if (content) {
              fullText += content;
              if (onChunk) onChunk(content);
            }
          }
        } catch (e) {
          console.error('Failed to parse SSE:', e);
        }
      }
    }
  } finally {
    reader.releaseLock();
  }

  return fullText;
}

function processMessageForOpenAI(message) {
  // If message doesn't have image data, return as-is
  if (!message.image) {
    return message;
  }

  // Process message with image
  const { image, content } = message;

  return {
    role: message.role,
    content: [
      {
        type: 'text',
        text: content
      },
      {
        type: 'image_url',
        image_url: {
          url: `data:${image.mimeType};base64,${image.data}`,
          detail: 'high'
        }
      }
    ]
  };
}

function processMessageForAnthropic(message) {
  // If message doesn't have image data, return as-is
  if (!message.image) {
    return message;
  }

  // Process message with image
  const { image, content } = message;

  return {
    role: message.role === 'assistant' ? 'assistant' : 'user',
    content: [
      {
        type: 'text',
        text: content
      },
      {
        type: 'image',
        source: {
          type: 'base64',
          media_type: image.mimeType,
          data: image.data
        }
      }
    ]
  };
}

