async function loadPapersByDateRange(startDate, endDate) {
  // 获取日期范围内的所有有效日期
  const validDatesInRange = availableDates.filter(date => {
    return date >= startDate && date <= endDate;
  });

  if (validDatesInRange.length === 0) {
    alert('No available papers in the selected date range.');
    return;
  }

  if (startDate === endDate) {  
    currentDate = startDate;
    document.getElementById('currentDate').textContent = formatDate(startDate);
  } else {
    currentDate = `${startDate} - ${endDate}`;
    document.getElementById('currentDate').textContent = `${formatDate(startDate)} - ${formatDate(endDate)}`;
  }

  const container = document.getElementById('papersList');
  container.innerHTML = `
    <div class="loading-container">
      <div class="loading-spinner"></div>
      <p>Loading papers from ${formatDate(startDate)} to ${formatDate(endDate)}...</p>
    </div>
  `;

  try {
    // 加载所有日期的论文数据
    const allPaperData = {};
    allPapersData = []; // 重置全局论文数据

    for (const date of validDatesInRange) {
      const selectedLanguage = selectLanguageForDate(date);
      // 从 data 分支获取数据文件
      const dataUrl = DATA_CONFIG.getDataUrl(`data/${date}_AI_enhanced_${selectedLanguage}.jsonl`);
      const response = await fetch(dataUrl);
      const text = await response.text();
      const dataPapers = parseJsonlData(text, date);

      // 合并数据
      Object.keys(dataPapers).forEach(category => {
        if (!allPaperData[category]) {
          allPaperData[category] = [];
        }
        allPaperData[category] = allPaperData[category].concat(dataPapers[category]);
        // 将论文添加到全局数组
        allPapersData = allPapersData.concat(dataPapers[category]);
      });
    }

    paperData = allPaperData;

    // 提取所有论文标题
    const allTitle = [];
    Object.keys(paperData).forEach(category => {
      paperData[category].forEach(paper => {
        allTitle.push(paper.title);
      });
    });

    // 提取关键词并进行总结
    const extractKeywords = (text) => {
      // 移除特殊字符和多余空格
      const cleanText = text.replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();

      // 使用 compromise 进行文本处理
      const doc = nlp(cleanText);

      // 提取名词短语和重要词汇
      const terms = new Set();

      // 提取名词短语
      doc.match('#Noun+').forEach(match => {
        const phrase = match.text().toLowerCase();
        if (phrase.split(' ').length <= 3) { // 最多3个词的短语
          terms.add(phrase);
        }
      });

      // 提取形容词+名词组合
      doc.match('(#Adjective+ #Noun+)').forEach(match => {
        const phrase = match.text().toLowerCase();
        if (phrase.split(' ').length <= 3) {
          terms.add(phrase);
        }
      });

      // 定义停用词
      const stopWords = new Set([
        'the', 'is', 'at', 'which', 'and', 'or', 'in', 'to', 'for', 'of', 
        'with', 'by', 'on', 'this', 'that', 'our', 'method', 'based', 
        'towards', 'via', 'multi', 'text', 'using', 'aware', 'data', 'from',
        'paper', 'propose', 'proposed', 'approach', 'model', 'system', 
        'framework', 'results', 'show', 'demonstrates', 'experimental', 
        'experiments', 'evaluation', 'performance', 'state', 'art', 'sota',
        'dataset', 'datasets', 'task', 'tasks', 'learning', 'neural', 
        'network', 'networks', 'deep', 'machine', 'artificial', 'intelligence', 
        'ai', 'ml', 'dl'
      ]);

      // 过滤停用词和短词
      const filteredTerms = Array.from(terms).filter(term => {
        const words = term.split(' ');
        return words.every(word => word.length > 2) && 
               !words.every(word => stopWords.has(word));
      });

      // 统计词频
      const termFreq = {};
      filteredTerms.forEach(term => {
        termFreq[term] = (termFreq[term] || 0) + 1;
        // 给多词短语更高的权重
        if (term.includes(' ')) {
          termFreq[term] *= 1.5;
        }
      });

      // 计算 TF 值（词频）
      const tfScores = {};
      const totalTerms = Object.values(termFreq).reduce((a, b) => a + b, 0);
      Object.entries(termFreq).forEach(([term, freq]) => {
        tfScores[term] = freq / totalTerms;
      });

      // 按 TF 值排序并返回前10个关键词/短语
      return Object.entries(tfScores)
        .sort(([,a], [,b]) => b - a)
        .slice(0, 10)
        .map(([term]) => term);
    };

    // 处理所有摘要
    const allKeywords = new Map();
    const keywordTrends = new Map(); // 添加关键词趋势数据结构

    // 初始化日期数据结构
    validDatesInRange.forEach(date => {
      keywordTrends.set(date, new Map());
    });

    // 按日期统计关键词
    allTitle.forEach((abstract, index) => {
      const date = validDatesInRange[Math.floor(index / (allTitle.length / validDatesInRange.length))];
      const keywords = extractKeywords(abstract);

      keywords.forEach(keyword => {
        // 更新总体统计
        allKeywords.set(keyword, (allKeywords.get(keyword) || 0) + 1);

        // 更新日期维度统计
        const dateStats = keywordTrends.get(date);
        dateStats.set(keyword, (dateStats.get(keyword) || 0) + 1);
      });
    });

    // 生成关键词云数据
    const keywordCloudData = Array.from(allKeywords.entries())
      .filter(([, count]) => count > 1)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 30)
      .map(([keyword, count]) => ({
        text: keyword,
        size: Math.max(12, Math.min(50, count * 3))
      }));

    // 准备折线图数据
    const top10Keywords = keywordCloudData.slice(0, 10).map(d => d.text);
    const trendData = top10Keywords.map(keyword => {
      return {
        keyword: keyword,
        values: Array.from(keywordTrends.entries()).map(([date, stats]) => ({
          date: new Date(date + 'T00:00:00Z'),  // 确保日期被正确解析，添加时间部分
          count: stats.get(keyword) || 0
        })).sort((a, b) => a.date - b.date)  // 确保数据按日期排序
      };
    });

    // 创建可视化展示
    container.innerHTML = `
      <div class="statistics-section">
        <h2>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M21.41 11.58L12.41 2.58C12.05 2.22 11.55 2 11 2H4C2.9 2 2 2.9 2 4V11C2 11.55 2.22 12.05 2.59 12.42L11.59 21.42C11.95 21.78 12.45 22 13 22C13.55 22 14.05 21.78 14.41 21.41L21.41 14.41C21.78 14.05 22 13.55 22 13C22 12.45 21.77 11.94 21.41 11.58ZM5.5 7C4.67 7 4 6.33 4 5.5C4 4.67 4.67 4 5.5 4C6.33 4 7 4.67 7 5.5C7 6.33 6.33 7 5.5 7Z" fill="currentColor"/>
          </svg>
          Popular Keywords
        </h2>
        <div class="statistics-card">
          <div class="keyword-list">
            ${keywordCloudData.map((item, index) => `
              <div class="keyword-item" onclick="showRelatedPapers('${item.text}')">
                <span class="keyword-rank">${index + 1}</span>
                <span class="keyword-text">${item.text}</span>
                <span class="keyword-count">${allKeywords.get(item.text)}</span>
              </div>
            `).join('')}
          </div>
        </div>

        ${startDate !== endDate ? `
        <h2 class="trend-title">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M3.5 18.5L9.5 12.5L13.5 16.5L22 6.92L20.59 5.5L13.5 13.5L9.5 9.5L2 17L3.5 18.5Z" fill="currentColor"/>
          </svg>
          Keywords Trend
        </h2>
        <div class="statistics-card">
          <div id="trendChart" style="width: 100%; height: 400px;"></div>
        </div>
        ` : ''}
      </div>
    `;

    // 只在日期范围模式下创建趋势图
    if (startDate !== endDate) {
      // 创建折线图
      const margin = {top: 20, right: 180, bottom: 80, left: 60}; // 增加底部边距以适应更长的日期标签
      const width = document.getElementById('trendChart').offsetWidth - margin.left - margin.right;
      const height = 400 - margin.top - margin.bottom;

      const svg = d3.select('#trendChart')
        .append('svg')
          .attr('width', width + margin.left + margin.right)
          .attr('height', height + margin.top + margin.bottom)
        .append('g')
          .attr('transform', `translate(${margin.left},${margin.top})`);

      // 设置比例尺
      const x = d3.scaleTime()
        .domain(d3.extent(validDatesInRange, d => new Date(d)))
        .range([0, width]);

      const y = d3.scaleLinear()
        .domain([0, d3.max(trendData, d => d3.max(d.values, v => v.count))])
        .range([height, 0]);

      // 创建颜色比例尺，使用更柔和的颜色
      const color = d3.scaleOrdinal()
        .range(['#4e79a7', '#f28e2c', '#59a14f', '#e15759', '#76b7b2', 
                '#edc949', '#af7aa1', '#ff9da7', '#9c755f', '#bab0ab']);

      // 添加X轴网格线
      svg.append('g')
        .attr('class', 'grid')
        .attr('transform', `translate(0,${height})`)
        .style('stroke-dasharray', '3,3')
        .style('opacity', 0.1)
        .call(d3.axisBottom(x)
          .ticks(8)
          .tickSize(-height)
          .tickFormat(''));

      // 添加Y轴网格线
      svg.append('g')
        .attr('class', 'grid')
        .style('stroke-dasharray', '3,3')
        .style('opacity', 0.1)
        .call(d3.axisLeft(y)
          .tickSize(-width)
          .tickFormat(''));

      // 添加一个函数来确定合适的日期格式
      function determineDateFormat(dates) {
        const startDate = new Date(dates[0]);
        const endDate = new Date(dates[dates.length - 1]);

        // 检查是否跨年
        const sameYear = startDate.getFullYear() === endDate.getFullYear();
        // 检查是否在同一个月
        const sameMonth = sameYear && startDate.getMonth() === endDate.getMonth();

        if (sameMonth) {
          return d3.timeFormat("%d"); // 只显示日
        } else if (sameYear) {
          return d3.timeFormat("%m-%d"); // 显示月-日
        } else {
          return d3.timeFormat("%Y-%m-%d"); // 显示完整日期
        }
      }

      // 获取日期格式化函数
      const dateFormat = determineDateFormat(validDatesInRange);

      // 添加X轴
      svg.append('g')
        .attr('class', 'x-axis')
        .attr('transform', `translate(0,${height})`)
        .call(d3.axisBottom(x)
          .ticks(Math.min(validDatesInRange.length, 8))
          .tickFormat(dateFormat))
        .selectAll("text")
        .style("text-anchor", "end")
        .style("font-size", "12px")
        .style("fill", "#666")
        .attr("dx", "-.8em")
        .attr("dy", ".15em")
        .attr("transform", "rotate(-45)");

      // 添加Y轴
      svg.append('g')
        .attr('class', 'y-axis')
        .call(d3.axisLeft(y)
          .ticks(5))
        .selectAll("text")
        .style("font-size", "12px")
        .style("fill", "#666");

      // 添加Y轴标题
      svg.append("text")
        .attr("transform", "rotate(-90)")
        .attr("y", 0 - margin.left)
        .attr("x", 0 - (height / 2))
        .attr("dy", "1em")
        .style("text-anchor", "middle")
        .style("fill", "#666")
        .style("font-size", "12px")
        .text("Frequency");

      // 添加X轴标题，显示年份和月份（如果被省略的话）
      const startDate = new Date(validDatesInRange[0]);
      const endDate = new Date(validDatesInRange[validDatesInRange.length - 1]);
      let xAxisTitle = "";

      if (startDate.getFullYear() === endDate.getFullYear()) {
        if (startDate.getMonth() === endDate.getMonth()) {
          xAxisTitle = `${startDate.getFullYear()}/${String(startDate.getMonth() + 1).padStart(2, '0')}`;
        } else {
          xAxisTitle = `${startDate.getFullYear()}`;
        }
      }

      if (xAxisTitle) {
        svg.append("text")
          .attr("transform", `translate(${width/2}, ${height + margin.bottom - 5})`)
          .style("text-anchor", "middle")
          .style("fill", "#666")
          .style("font-size", "12px")
          .text(xAxisTitle);
      }

      // 加粗坐标轴线条
      svg.selectAll('.x-axis path, .y-axis path, .x-axis line, .y-axis line')
        .style('stroke', '#666')
        .style('stroke-width', '1.5px');

      // 定义面积生成器
      const area = d3.area()
        .x(d => x(d.date))
        .y0(height)
        .y1(d => y(d.count))
        .curve(d3.curveBasis); // 使用更平滑的曲线

      // 定义线条生成器
      const line = d3.line()
        .x(d => x(d.date))
        .y(d => y(d.count))
        .curve(d3.curveBasis); // 使用相同的平滑曲线

      // 添加渐变定义
      const gradient = svg.append("defs")
        .selectAll("linearGradient")
        .data(trendData)
        .enter()
        .append("linearGradient")
        .attr("id", (d, i) => `gradient-${i}`)
        .attr("x1", "0%")
        .attr("y1", "0%")
        .attr("x2", "0%")
        .attr("y2", "100%");

      gradient.append("stop")
        .attr("offset", "0%")
        .attr("stop-color", d => color(d.keyword))
        .attr("stop-opacity", 0.3);

      gradient.append("stop")
        .attr("offset", "100%")
        .attr("stop-color", d => color(d.keyword))
        .attr("stop-opacity", 0.05);

      // 绘制面积
      const areas = svg.selectAll('.area')
        .data(trendData)
        .enter()
        .append('path')
          .attr('class', 'area')
          .attr('d', d => area(d.values))
          .style('fill', (d, i) => `url(#gradient-${i})`)
          .style('opacity', 0.7);

      // 绘制折线
      const paths = svg.selectAll('.line')
        .data(trendData)
        .enter()
        .append('path')
          .attr('class', 'line')
          .attr('d', d => line(d.values))
          .style('stroke', d => color(d.keyword))
          .style('fill', 'none')
          .style('stroke-width', 2)
          .style('opacity', 0.8);

      // 添加图例
      const legend = svg.selectAll('.legend')
        .data(trendData)
        .enter()
        .append('g')
          .attr('class', 'legend')
          .attr('transform', (d, i) => `translate(${width + 20},${i * 25})`);

      legend.append('rect')
        .attr('x', 0)
        .attr('width', 18)
        .attr('height', 18)
        .style('fill', d => color(d.keyword))
        .style('opacity', 0.7);

      legend.append('text')
        .attr('x', 28)
        .attr('y', 13)
        .text(d => d.keyword)
        .style('font-size', '12px')
        .style('alignment-baseline', 'middle');

      // 添加交互效果
      legend.style('cursor', 'pointer')
        .on('mouseover', function(event, d) {
          const keyword = d.keyword;

          // 降低其他线条和区域的透明度
          areas.style('opacity', 0.1);
          paths.style('opacity', 0.1);

          // 高亮当前选中的线条和区域
          svg.selectAll('.area')
            .filter(p => p.keyword === keyword)
            .style('opacity', 0.9);

          svg.selectAll('.line')
            .filter(p => p.keyword === keyword)
            .style('opacity', 1)
            .style('stroke-width', 3);
        })
        .on('mouseout', function() {
          // 恢复原始状态
          areas.style('opacity', 0.7);
          paths.style('opacity', 0.8)
            .style('stroke-width', 2);
        });
    }

  } catch (error) {
    console.error('加载论文数据失败:', error);
    container.innerHTML = `
      <div class="loading-container">
        <p>Loading data fails. Please retry.</p>
        <p>Error messages: ${error.message}</p>
      </div>
    `;
  }
}

function registerWindowHandlers({ windowManager, checkASRReady }) {
  // 渲染进程日志转发（可选）
  ipcMain.on('log', (_event, message) => {
    try {
      if (message === undefined) return;
      console.log('[RendererLog]', message);
    } catch {
      // ignore
    }
  });

  // 显示 HUD
  ipcMain.on('show-hud', async () => {
    // 如果正在创建，弹一次提示，避免用户频繁点击
    if (windowManager.hudCreating) {
      if (!windowManager.hudCreateNotified) {
        windowManager.hudCreateNotified = true;
        const parent = windowManager.getMainWindow();
        const message = 'ASR 模型正在加载，可能需要十几秒，请稍等片刻，无需重复点击。';
        console.log('[HUD]', message);
        const dialogOpts = {
          type: 'info',
          buttons: ['好的'],
          title: '正在加载',
          message
        };
        if (parent) {
          parent.webContents.send('hud-loading', { message });
        }
        electron.dialog.showMessageBox(parent || null, dialogOpts).catch(() => {});
      }
      return;
    }

    if (!windowManager.getHUDWindow()) {
      await windowManager.createHUDWindow(() => checkASRReady(), () => {});
    } else {
      windowManager.showHUD();
    }
    console.log('HUD显示');
  });

  // 隐藏 HUD
  ipcMain.on('hide-hud', () => {
    windowManager.hideHUD();
    console.log('HUD隐藏');
  });

  // 关闭 HUD
  ipcMain.on('close-hud', () => {
    windowManager.closeHUD();
    console.log('HUD关闭');
  });

  // HUD 拖拽
  ipcMain.on('start-hud-drag', (event, pos) => {
    windowManager.startHUDrag(pos);
  });

  ipcMain.on('update-hud-drag', (event, pos) => {
    windowManager.updateHUDrag(pos);
  });

  ipcMain.on('end-hud-drag', () => {
    windowManager.endHUDrag();
  });

  // 主窗口控制
  ipcMain.on('minimize-window', () => {
    windowManager.minimizeMainWindow();
  });

  ipcMain.on('close-window', () => {
    windowManager.closeMainWindow();
  });

  // 主窗口拖拽
  ipcMain.on('start-drag', (event, pos) => {
    windowManager.startMainDrag(pos);
  });

  ipcMain.on('update-drag', (event, pos) => {
    windowManager.updateMainDrag(pos);
  });

  ipcMain.on('end-drag', () => {
    windowManager.endMainDrag();
  });

  // 对话建议配置更新后通知 HUD 重新加载配置
  ipcMain.on('suggestion-config-updated', () => {
    const hudWin = windowManager.getHUDWindow?.();
    if (hudWin && !hudWin.isDestroyed()) {
      hudWin.webContents.send('suggestion-config-updated');
    }
  });

  console.log('Window IPC handlers registered');
}

async function ensurePortIsFree(port) {
  try {
    await killPort(port);
    console.log(`Port ${port} was occupied and has been released.`);
  } catch (error) {
    if (
      error?.message?.includes('does not appear to be running') ||
      error?.code === 'ECONNREFUSED'
    ) {
      // There was nothing to kill, which is fine.
      return;
    }
    console.warn(`Failed to release port ${port}: ${error?.message ?? error}`);
  }
}

function float32ToInt16Buffer(floatArray) {
  const int16Array = new Int16Array(floatArray.length);
  for (let i = 0; i < floatArray.length; i += 1) {
    const sample = Math.max(-1, Math.min(1, floatArray[i]));
    int16Array[i] = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
  }
  return Buffer.from(int16Array.buffer);
}

setServerCrashCallback(callback) {
    this.onServerCrash = callback;
  }

detectPythonPath() {
    const envPython = process.env.ASR_PYTHON_PATH;
    if (envPython && fs.existsSync(envPython)) {
      return envPython;
    }
    const projectRoot = path.resolve(app.getAppPath(), app.isPackaged ? '../..' : '.');
    const venvPython = path.join(projectRoot, '.venv', 'bin', 'python');
    if (fs.existsSync(venvPython)) {
      return venvPython;
    }
    // Windows 下可能是 python.exe
    if (process.platform === 'win32') {
      const venvPythonWin = path.join(projectRoot, '.venv', 'Scripts', 'python.exe');
      if (fs.existsSync(venvPythonWin)) {
        return venvPythonWin;
      }
    }
    return 'python3';
  }

async startWorker() {
    if (this.workerProcess) return;

    const args = [this.workerScriptPath];

    // 设置环境变量
    const env = {
      ...process.env,
      PYTHONUNBUFFERED: '1',
      ASR_MODEL: this.modelName,
      PYTHONIOENCODING: 'utf-8'
    };

    logger.log(`[LocalWhisper] Spawning worker: ${this.pythonPath} ${args.join(' ')}`);

    this.workerProcess = spawn(this.pythonPath, args, { env });

    // 处理标准输出（来自 worker 的 JSON 消息）
    this.workerProcess.stdout.on('data', (data) => {
      const lines = data.toString().split('\n');
      for (const line of lines) {
        if (!line.trim()) continue;
        try {
          const msg = JSON.parse(line);
          this.handleWorkerMessage(msg);
        } catch (e) {
          // 忽略非 JSON 输出
        }
      }
    });

    // 处理标准错误（日志）
    this.workerProcess.stderr.on('data', (data) => {
      logger.log(`[LocalWhisper][Worker] ${data.toString().trim()}`);
    });

    this.workerProcess.on('close', (code) => {
      logger.warn(`[LocalWhisper] Worker exited with code ${code}`);
      this.workerProcess = null;
      this.isInitialized = false;
      if (this.onServerCrash) {
        this.onServerCrash(code);
      }
    });

    // 等待 Worker 就绪
    // 这里简单等待一下，实际可以用 Promise 等待 "ready" 消息
    // 但为了保持简单，假设启动成功
    await delay(1000);
  }

handleWorkerMessage(msg) {
    if (msg.type === 'partial') {
      if (this.onPartialResult) {
        this.onPartialResult({
          sessionId: msg.session_id,
          partialText: msg.text,
          fullText: msg.full_text,
          timestamp: msg.timestamp,
          isSpeaking: true
        });
      }
    } else if (msg.type === 'sentence_complete') {
      if (this.onSentenceComplete) {
        this.onSentenceComplete({
          sessionId: msg.session_id,
          text: msg.text,
          timestamp: msg.timestamp,
          trigger: msg.trigger || 'worker',
          audioDuration: msg.audio_duration,
          language: msg.language
        });
      }
    } else if (msg.status === 'ready') {
      logger.log('[LocalWhisper] Worker is ready');
    } else if (msg.error) {
      logger.error(`[LocalWhisper] Worker error: ${msg.error}`);
    }
  }

async addAudioChunk(audioData, timestamp, sourceId = 'default') {
    if (!this.workerProcess) return;

    if (!audioData || audioData.length === 0) return;

    // 【优化】提高静音检测阈值，减少误触发
    // 简单的静音检测（虽然 worker 也有 VAD）
    if (this.detectSilence(audioData)) {
      if (!this.silenceTimer) {
        this.silenceTimer = setTimeout(() => {
          this.forceCommitSentence(sourceId);
          this.silenceTimer = null;
        }, 1500); // 【优化】从700ms提高到1500ms，减少句子截断
      }
      return;
    }

    if (this.silenceTimer) {
      clearTimeout(this.silenceTimer);
      this.silenceTimer = null;
    }

    const buffer = float32ToInt16Buffer(audioData);
    const base64Audio = buffer.toString('base64');

    const msg = {
      type: 'streaming_chunk',
      session_id: sourceId,
      audio_data: base64Audio,
      timestamp: timestamp
    };

    this.sendToWorker(msg);
  }

sendToWorker(msg) {
    if (this.workerProcess && this.workerProcess.stdin.writable) {
      this.workerProcess.stdin.write(JSON.stringify(msg) + '\n');
    }
  }

detectSilence(audioData) {
    let sum = 0;
    for (let i = 0; i < audioData.length; i += 1) {
      sum += Math.abs(audioData[i]);
    }
    const average = sum / audioData.length;
    // 【优化】提高阈值，减少误判
    return average < 0.003;
  }

function parsePageRange(rangeString, totalPages) {
  const pages = new Set();
  const parts = rangeString.split(',').map(s => s.trim());

  for (const part of parts) {
    if (part.includes('-')) {
      const [start, end] = part.split('-').map(s => parseInt(s.trim(), 10));
      if (isNaN(start) || isNaN(end)) continue;
      for (let i = Math.max(1, start); i <= Math.min(totalPages, end); i++) {
        pages.add(i);
      }
    } else {
      const pageNum = parseInt(part, 10);
      if (!isNaN(pageNum) && pageNum >= 1 && pageNum <= totalPages) {
        pages.add(pageNum);
      }
    }
  }

  return Array.from(pages).sort((a, b) => a - b);
}

function addAttachmentsToPDFInWorker(pdfBuffer, attachmentBuffers, attachmentNames, attachmentLevel, pageRange) {
  try {
    const uint8Array = new Uint8Array(pdfBuffer);

    let pdf;
    try {
      pdf = coherentpdf.fromMemory(uint8Array, '');
    } catch (error) {
      const errorMsg = error.message || error.toString();

      if (errorMsg.includes('Failed to read PDF') ||
        errorMsg.includes('Could not read object') ||
        errorMsg.includes('No /Root entry') ||
        errorMsg.includes('PDFError')) {
        self.postMessage({
          status: 'error',
          message: 'The PDF file has structural issues and cannot be processed. The file may be corrupted, incomplete, or created with non-standard tools. Please try:\n\n• Opening and re-saving the PDF in another PDF viewer\n• Using a different PDF file\n• Repairing the PDF with a PDF repair tool'
        });
      } else {
        self.postMessage({
          status: 'error',
          message: `Failed to load PDF: ${errorMsg}`
        });
      }
      return;
    }

    const totalPages = coherentpdf.pages(pdf);

    let targetPages = [];
    if (attachmentLevel === 'page') {
      if (!pageRange) {
        self.postMessage({
          status: 'error',
          message: 'Page range is required for page-level attachments.'
        });
        coherentpdf.deletePdf(pdf);
        return;
      }
      targetPages = parsePageRange(pageRange, totalPages);
      if (targetPages.length === 0) {
        self.postMessage({
          status: 'error',
          message: 'Invalid page range specified.'
        });
        coherentpdf.deletePdf(pdf);
        return;
      }
    }

    for (let i = 0; i < attachmentBuffers.length; i++) {
      try {
        const attachmentData = new Uint8Array(attachmentBuffers[i]);
        const attachmentName = attachmentNames[i];

        if (attachmentLevel === 'document') {
          coherentpdf.attachFileFromMemory(attachmentData, attachmentName, pdf);
        } else {
          for (const pageNum of targetPages) {
            coherentpdf.attachFileToPageFromMemory(attachmentData, attachmentName, pdf, pageNum);
          }
        }
      } catch (error) {
        console.warn(`Failed to attach file ${attachmentNames[i]}:`, error);
        self.postMessage({
          status: 'error',
          message: `Failed to attach file ${attachmentNames[i]}: ${error.message || error}`
        });
        coherentpdf.deletePdf(pdf);
        return;
      }
    }

    // Save the modified PDF
    const modifiedBytes = coherentpdf.toMemory(pdf, false, false);
    coherentpdf.deletePdf(pdf);

    const buffer = modifiedBytes.buffer.slice(
      modifiedBytes.byteOffset,
      modifiedBytes.byteOffset + modifiedBytes.byteLength
    );

    self.postMessage({
      status: 'success',
      modifiedPDF: buffer
    }, [buffer]);

  } catch (error) {
    self.postMessage({
      status: 'error',
      message: error instanceof Error
        ? error.message
        : 'Unknown error occurred while adding attachments.'
    });
  }
}

function hasCJKCharacters(text) {
    if (!text) return false;
    const cjkRegex = /[\u4E00-\u9FFF\u3040-\u309F\u30A0-\u30FF\uAC00-\uD7AF\u3400-\u4DBF\uF900-\uFAFF]/g;
    return cjkRegex.test(text);
}

async function extractTextFromXLSX(arrayBuffer) {
    try {
        const textDecoder = new TextDecoder('utf-8', { fatal: false });
        const fullText = textDecoder.decode(arrayBuffer);
        const textMatches = fullText.match(/<t[^>]*>([^<]*)<\/t>/gi) || [];
        let extractedText = '';
        for (const match of textMatches) {
            extractedText += match.replace(/<[^>]+>/g, '') + ' ';
        }
        return extractedText;
    } catch (e) {
        return '';
    }
}

async function loadCJKFont() {
    if (cjkFontLoaded) return true;

    self.postMessage({ type: 'status', message: 'Downloading CJK fonts...' });

    const fontSources = [
        'https://raw.githubusercontent.com/googlefonts/noto-cjk/main/Sans/OTF/SimplifiedChinese/NotoSansCJKsc-Regular.otf',
        'https://cdn.jsdelivr.net/gh/googlefonts/noto-cjk@main/Sans/OTF/SimplifiedChinese/NotoSansCJKsc-Regular.otf',
        'https://unpkg.com/@aspect-build/aspect-font@1.0.0/fonts/NotoSansSC-Regular.otf'
    ];

    for (const fontUrl of fontSources) {
        try {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 30000);
            const response = await fetch(fontUrl, { signal: controller.signal, cache: 'force-cache' });
            clearTimeout(timeoutId);

            if (response.ok) {
                const fontData = await response.arrayBuffer();
                if (fontData.byteLength > 1000000) {
                    pyodide.FS.writeFile('custom_font.otf', new Uint8Array(fontData));
                    cjkFontLoaded = true;
                    self.postMessage({ type: 'status', message: 'CJK font loaded!' });
                    return true;
                }
            }
        } catch (e) {
            console.warn(`Font download failed from ${fontUrl}`);
        }
    }
    return false;
}

async function detectCJKInXLSX(arrayBuffer) {
    try {
        const extractedText = await extractTextFromXLSX(arrayBuffer);
        if (hasCJKCharacters(extractedText)) return true;
        const textDecoder = new TextDecoder('utf-8', { fatal: false });
        const rawText = textDecoder.decode(arrayBuffer);
        return hasCJKCharacters(rawText);
    } catch (e) {
        return false;
    }
}

function uint8ArrayToBase64(bytes) {
  let binary = "";
  const chunkSize = 32768;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    const chunk = bytes.subarray(i, Math.min(i + chunkSize, bytes.length));
    binary += String.fromCharCode.apply(null, Array.from(chunk));
  }
  return btoa(binary);
}

