function Dec(
  input,
  key,
  TOTPEpoch = null,
  TOTPBaseKey = null,
  callback = null
) {
  //初始化
  //input.output Uint8Array
  let AdvancedEncObj = null;
  let AdvancedMarker = false;
  let WenyanSimulatorObj = new WenyanSimulator(key, callback);
  let OriginStr = Uint8ArrayTostring(input.output);

  //解映射
  let TempStr1 = WenyanSimulatorObj.deMap(OriginStr);

  let TempStr2Int = new Uint8Array();

  if (TempStr1.slice(0, 13).indexOf(ADVANCED_ENC_MAGIC) !== -1) {
    //检测高级加密标志

    TempStr1 =
      TempStr1.slice(0, TempStr1.slice(0, 13).indexOf(ADVANCED_ENC_MAGIC)) +
      TempStr1.slice(TempStr1.slice(0, 13).indexOf(ADVANCED_ENC_MAGIC) + 2); //移除高级加密标志

    AdvancedMarker = true;
  }

  if (!Base64.isValid(TempStr1)) {
    /* v8 ignore next 3 */
    //检查Base64是否合法，如果不合法，那么就没有必要继续处理下去
    throw "Error Decoding. Bad Input or Incorrect Key.";
  }
  try {
    //取到IV，然后对AES加密后的数据执行解密。
    TempStr2Int = Base64.toUint8Array(TempStr1);

    if (AdvancedMarker) {
      //读取高级加密配置
      let rawconfig = unpackByte(TempStr2Int.at(TempStr2Int.byteLength - 1));
      AdvancedEncObj = new AdvancedEncConfig(
        true,
        rawconfig.flags.b0,
        rawconfig.flags.b1,
        rawconfig.flags.b2,
        rawconfig.flags.b3,
        rawconfig.size,
        TOTPEpoch === null ? Date.now() : TOTPEpoch,
        TOTPBaseKey === null ? key : TOTPBaseKey
      );

      //解密
      TempStr2Int = Decrypt(TempStr2Int.slice(0, -1), key, AdvancedEncObj);
    } else {
      TempStr2Int = Decrypt(TempStr2Int, key, AdvancedEncObj);
    }

    //解压缩
    TempStr2Int = Decompress(TempStr2Int);
  } catch (err) {
    //解压缩/解密失败，丢出错误。
    /* v8 ignore next 6 */
    if (typeof err == "string") {
      throw err;
    } else {
      throw "Error Decoding. Bad Input or Incorrect Key.";
    }
  }

  if (!CheckLuhnBit(TempStr2Int)) {
    /* v8 ignore next 3 */
    //检查密文的校验位是否匹配
    //校验不通过，则丢出错误。
    throw "Error Decrypting. Checksum Mismatch.";
  } else {
    //校验通过，则移除校验位。
    TempStr2Int = TempStr2Int.subarray(0, TempStr2Int.byteLength - 1);
  }

  //到此，TempStr2Int 就是解密的结果，也就是原始数据(UINT8Array)。
  let Res = new Object();

  //组装一个对象，同时返回两种类型的解密结果。
  Res.output = Uint8ArrayTostring(TempStr2Int);
  Res.output_B = TempStr2Int;

  return Res;
}

function Enc_OLD(input, key, q) {
  //初始化
  let OldMapperObj = new OldMapper(key);

  let OriginalData = new Uint8Array();
  OriginalData = input.output;

  let TempArray = new Uint8Array(OriginalData.byteLength + 1);
  TempArray.set(OriginalData, 0);

  TempArray.set([GetLuhnBit(OriginalData)], OriginalData.byteLength);
  //压缩
  OriginalData = Compress(TempArray);
  //加密
  OriginalData = Encrypt(OriginalData, key);

  let OriginStr = RemovePadding(Base64.fromUint8Array(OriginalData));
  //映射
  let Res = OldMapperObj.enMap(OriginStr, q);

  return Res;
}

function Dec_OLD(input, key) {
  //初始化
  let OldMapperObj = new OldMapper(key);
  let OriginStr = Uint8ArrayTostring(input.output);

  //解映射
  let TempStr1 = OldMapperObj.deMap(OriginStr);

  //还原出AES加密之后的Base64 TempStr1

  let TempStr2Int = new Uint8Array();
  let RandomBytes = new Array(2);
  if (!Base64.isValid(TempStr1)) {
    throw "Error Decoding. Bad Input or Incorrect Key.";
  }
  try {
    TempStr2Int = Base64.toUint8Array(TempStr1);

    //解密
    TempStr2Int = Decrypt(TempStr2Int, key);

    //解压缩
    TempStr2Int = Decompress(TempStr2Int);
  } catch (err) {
    throw "Error Decoding. Bad Input or Incorrect Key.";
  }

  //校验数据
  if (!CheckLuhnBit(TempStr2Int)) {
    /* v8 ignore next 9 */
    if (
      TempStr2Int.at(TempStr2Int.byteLength - 1) == 2 &&
      TempStr2Int.at(TempStr2Int.byteLength - 2) == 2 &&
      TempStr2Int.at(TempStr2Int.byteLength - 3) == 2
    ) {
      TempStr2Int = TempStr2Int.subarray(0, TempStr2Int.byteLength - 3);
    } else {
      throw "Error Decrypting. Checksum Mismatch.";
    }
  } else {
    TempStr2Int = TempStr2Int.subarray(0, TempStr2Int.byteLength - 1);
  }

  //到此，TempStr2Int 就是解密的结果，形式为字节码。
  let Res = new Object();

  Res.output = Uint8ArrayTostring(TempStr2Int);
  Res.output_B = TempStr2Int;
  return Res;
}

WenyanInput(
    input,
    mode,
    key = "ABRACADABRA",
    WenyanConfigObj = new Core.WenyanConfig(true, 50, false, false),
    AdvancedEncObj = new Core.AdvancedEncConfig(),
    callback = null
  ) {
    //开始处理
    if (this.#input == Abracadabra.UINT8) {
      //如果指定输入类型是UINT8
      if (Object.prototype.toString.call(input) != "[object Uint8Array]") {
        throw "Unexpected Input Type";
      }
      if (mode == Abracadabra.ENCRYPT) {
        let Nextinput = new Object();
        Nextinput.output = input;
        this.#res = Core.Enc(
          Nextinput,
          key,
          WenyanConfigObj,
          AdvancedEncObj,
          callback
        );
      } else if (mode == Abracadabra.DECRYPT) {
        let Nextinput = new Object();
        Nextinput.output = input;
        this.#res = Core.Dec(
          Nextinput,
          key,
          AdvancedEncObj.TOTPEpoch,
          AdvancedEncObj.TOTPBaseKey,
          callback
        );
      }
      return 0;
    } else if (this.#input == Abracadabra.TEXT) {
      //如果指定输入类型是TEXT
      if (Object.prototype.toString.call(input) != "[object String]") {
        throw "Unexpected Input Type";
      }
      let Nextinput = new Object();
      Nextinput.output = stringToUint8Array(input);
      if (mode == Abracadabra.ENCRYPT) {
        this.#res = Core.Enc(
          Nextinput,
          key,
          WenyanConfigObj,
          AdvancedEncObj,
          callback
        );
      } else if (mode == Abracadabra.DECRYPT) {
        this.#res = Core.Dec(
          Nextinput,
          key,
          AdvancedEncObj.TOTPEpoch,
          AdvancedEncObj.TOTPBaseKey,
          callback
        );
      }
      return 0;
    }
    return 0;
  }

OldInput(input, mode, key = "ABRACADABRA", q = false) {
    if (this.#input == Abracadabra.UINT8) {
      //如果指定输入类型是UINT8
      if (Object.prototype.toString.call(input) != "[object Uint8Array]") {
        throw "Unexpected Input Type";
      }
      //对于输入UINT8的情况，先尝试将数据转换成字符串进行预检。
      let Decoder = new TextDecoder("utf-8", { fatal: true });
      let NoNeedtoPreCheck = false;
      let inputString = String();
      try {
        inputString = Decoder.decode(input);
      } catch (err) {
        //指定了Fatal，如果在解码时出现错误，则无需再执行预检
        NoNeedtoPreCheck = true;
      }
      let preCheckRes;
      if (!NoNeedtoPreCheck) {
        //如果给定的数据是一个可解码的字符串，那么解码预检
        //此时参照预检结果和指定的模式进行判断
        preCheckRes = preCheck_OLD(inputString);

        if (
          (preCheckRes.isEncrypted && mode != Abracadabra.ENCRYPT) ||
          mode == Abracadabra.DECRYPT
        ) {
          //如果是加密的字符串且没有强制指定要再次加密，或者强制执行解密,自动执行解密
          //如果是加密的字符串,指定AUTO在此处会自动解密
          this.#res = Core.Dec_OLD(preCheckRes, key);
        } else {
          this.#res = Core.Enc_OLD(preCheckRes, key, q); //在字符串可解码的情况下，加密时不采用文件模式
        }
      } else {
        //如果给定的数据不可预检(不可能是密文，此时强制解密无效)，直接对数据传递给加密函数
        preCheckRes = new PreCheckResult(input, true);
        this.#res = Core.Enc_OLD(preCheckRes, key, q);
      }
    } else if (this.#input == Abracadabra.TEXT) {
      //如果指定输入类型是TEXT
      if (Object.prototype.toString.call(input) != "[object String]") {
        throw "Unexpected Input Type";
      }
      let preCheckRes = preCheck_OLD(input);
      if (
        (preCheckRes.isEncrypted && mode != Abracadabra.ENCRYPT) ||
        mode == Abracadabra.DECRYPT
      ) {
        //如果是加密的字符串且没有强制指定要再次加密，或者强制执行解密,自动执行解密
        //如果是加密的字符串,指定AUTO在此处会自动解密
        this.#res = Core.Dec_OLD(preCheckRes, key);
      } else {
        this.#res = Core.Enc_OLD(preCheckRes, key, q); //在字符串可解码的情况下，加密时不采用文件模式
      }
    }
    return 0;
  }

Output() {
    if (this.#res == null) {
      throw "Null Output, please input some data at first.";
    }
    if (typeof this.#res == "object") {
      if (this.#output == Abracadabra.TEXT) {
        return this.#res.output; //要输出字符串，那么直接输出字符串，解密总会有字符串
      } else {
        //如果要输出UINT8
        if (this.#res.output_B != null) {
          //如果有现成的可用，直接输出现成的。
          return this.#res.output_B;
        } else {
          //如果没有现成的，那么就要转换一下再输出
          const encoder = new TextEncoder();
          const encodedData = encoder.encode(this.#res.output);

          return encodedData;
        }
      }
    } else if (typeof this.#res == "string") {
      //如果是字符串类型，那么就是加密结果
      if (this.#output == Abracadabra.TEXT) {
        return this.#res; //要输出字符串，那么直接输出字符串，解密总会有字符串
      } else {
        //如果要输出UINT8
        //没有现成的，那么就要转换一下再输出
        const encoder = new TextEncoder();
        const encodedData = encoder.encode(this.#res);
        return encodedData;
      }
    }
    return undefined;
  }

