    const id = name.toLowerCase().replace(/[^a-z0-9-]/g, '-').replace(/-+/g, '-');
    const newAgent = { id, name, path: filePath };

    // Check if agent already exists
    const existingIndex = agents.findIndex(a => a.id === id);
    if (existingIndex >= 0) {
