normalizeChunk(chunk) {
    if (!chunk) return null;

    // Handle different chunk types from Opencode
    if (chunk.type === 'text' || chunk.type === 'content') {
      return {
        type: 'text',
        content: chunk.text || chunk.content || '',
        provider: this.name
      };
    }

    if (chunk.type === 'tool_use' || chunk.type === 'tool_call') {
      console.log('[Opencode] Tool use:', chunk.name || chunk.tool);
      return {
        type: 'tool_use',
        name: chunk.name || chunk.tool,
        input: chunk.input || chunk.arguments || {},
        id: chunk.id || chunk.tool_call_id,
        provider: this.name
      };
    }

    if (chunk.type === 'tool_result') {
      return {
        type: 'tool_result',
        result: chunk.result || chunk.output || chunk.content,
        tool_use_id: chunk.tool_use_id || chunk.tool_call_id,
        provider: this.name
      };
    }

    // Pass through other chunk types
    return {
      ...chunk,
      provider: this.name
    };
  }

function compareVersions(version1, version2) {
	const v1parts = version1.split(".").map(Number);
	const v2parts = version2.split(".").map(Number);

	const maxLength = Math.max(v1parts.length, v2parts.length);

	for (let i = 0; i < maxLength; i++) {
		const v1part = v1parts[i] || 0;
		const v2part = v2parts[i] || 0;

		if (v1part > v2part) return 1;
		if (v1part < v2part) return -1;
	}

	return 0;
}

async function checkPublicRepo(owner, repo) {
	try {
		const httpsRepoUrl = `https://api.github.com/repos/${owner}/${repo}/releases/latest`;

		// Get current version for User-Agent (or use generic if unavailable)
		let currentVersion = "unknown";
		try {
			// Use __dirname to construct absolute path to package.json
			const packageJsonPath = path.join(__dirname, "../../../package.json");
			const packageJsonContent = fs.readFileSync(packageJsonPath, "utf8");
			const packageJson = JSON.parse(packageJsonContent);
			if (packageJson?.version) {
				currentVersion = packageJson.version;
			}
		} catch (packageError) {
			console.warn(
				"Could not read version from package.json for User-Agent:",
				packageError.message,
			);
		}

		const response = await fetch(httpsRepoUrl, {
			method: "GET",
			headers: {
				Accept: "application/vnd.github.v3+json",
				"User-Agent": `PatchMon-Server/${currentVersion}`,
			},
		});

		if (!response.ok) {
			const errorText = await response.text();
			if (
				errorText.includes("rate limit") ||
				errorText.includes("API rate limit")
			) {
				console.log("⚠️ GitHub API rate limit exceeded, skipping update check");
				return null;
			}
			throw new Error(
				`GitHub API error: ${response.status} ${response.statusText}`,
			);
		}

		const releaseData = await response.json();
		return releaseData.tag_name.replace("v", "");
	} catch (error) {
		console.error("GitHub API error:", error.message);
		throw error;
	}
}

