            const ref = ref_match[1];
            const role_match = trimmed.match(/^-\s+([a-zA-Z]+)/);
            if (!role_match)
                continue;
            const role = role_match[1];
            if (!this.INTERACTIVE_ROLES.has(role))
                continue;
            const name_match = trimmed.match(/"([^"]*)"/);
            const name = name_match ? name_match[1] : '';

            let url = null;
            const next_line_index = lines.indexOf(line)+1;
            if (next_line_index<lines.length)
            {
                const next_line = lines[next_line_index];
                const url_match = next_line.match(/\/url:\s*(.+)/);
                if (url_match)
                    url = url_match[1].trim().replace(/^["']|["']$/g, '');
            }
            elements.push({ref, role, name, url});
        }
        return elements;
    }

static format_compact(elements){
        const lines = [];
        for (const el of elements)
        {
            const parts = [`[${el.ref}]`, el.role];
            if (el.name && el.name.length>0)
            {
                const name = el.name.length>60 ?
                    el.name.substring(0, 57)+'...' : el.name;
                parts.push(`"${name}"`);
            }
            if (el.url && el.url.length>0 && !el.url.startsWith('#'))
            {
                let url = el.url;
                if (url.length>50)
                    url = url.substring(0, 47)+'...';
                parts.push(`-> ${url}`);
            }
            lines.push(parts.join(' '));
        }
        return lines.join('\n');
    }

static filter_snapshot(snapshot_text){
        try {
            const elements = this.parse_playwright_snapshot(snapshot_text);
            if (elements.length==0)
                return 'No interactive elements found';
            return this.format_compact(elements);
        } catch(e){
            return `Error filtering snapshot: ${e.message}\n${e.stack}`;
        }
    }

async function GET(Astro) {
  const { SITE_URL } = Astro.locals
  const tag = Astro.url.searchParams.get('tag')
  const channel = await getChannelInfo(Astro, {
    q: tag ? `#${tag}` : '',
  })
  const posts = channel.posts || []

  const request = Astro.request
  const url = new URL(request.url)
  url.pathname = SITE_URL
  url.search = ''

  const response = await rss({
    title: `${tag ? `${tag} | ` : ''}${channel.title}`,
    description: channel.description,
    site: url.origin,
    trailingSlash: false,
    stylesheet: getEnv(import.meta.env, Astro, 'RSS_BEAUTIFY') ? '/rss.xsl' : undefined,
    items: posts.map(item => ({
      link: `posts/${item.id}`,
      title: item.title,
      description: item.description,
      pubDate: new Date(item.datetime),
      content: sanitizeHtml(item.content, {
        allowedTags: sanitizeHtml.defaults.allowedTags.concat(['img', 'video', 'audio']),
        allowedAttributes: {
          ...sanitizeHtml.defaults.allowedAttributes,
          video: ['src', 'width', 'height', 'poster'],
          audio: ['src', 'controls'],
          img: ['src', 'srcset', 'alt', 'title', 'width', 'height', 'loading', 'class'],
        },
        exclusiveFilter(frame) {
          return frame.tag === 'img' && frame.attribs?.class?.includes('modal-img')
        },
      }),
    })),
  })

  response.headers.set('Content-Type', 'text/xml')
  response.headers.set('Cache-Control', 'public, max-age=3600')

  return response
}

function getEnv(env, Astro, name) {
  return env[name] ?? Astro.locals?.runtime?.env?.[name]
}

function normalizeEmoji(emoji) {
  const emojiMap = {
    '\u2764': '\u2764\uFE0F',
    '\u263A': '\u263A\uFE0F',
    '\u2639': '\u2639\uFE0F',
    '\u2665': '\u2764\uFE0F',
  }
  return emojiMap[emoji] || emoji
}

function getCustomEmojiImage(emojiId, staticProxy = '') {
  if (!emojiId)
    return null
  const imageUrl = `https://t.me/i/emoji/${emojiId}.webp`
  return `${staticProxy}${imageUrl}`
}

async function hydrateTgEmoji($, content, { staticProxy } = {}) {
  const emojiNodes = $(content).find('tg-emoji')?.toArray() ?? []
  if (!emojiNodes.length)
    return

  await Promise.all(emojiNodes.map((emojiEl) => {
    const emojiId = $(emojiEl).attr('emoji-id')
    if (!emojiId)
      return

    const imageUrl = getCustomEmojiImage(emojiId, staticProxy)
    if (imageUrl) {
      const imageMarkup = `<img class="tg-emoji" src="${imageUrl}" alt="" loading="lazy" />`
      $(emojiEl).replaceWith(imageMarkup)
    }
  }))
}

function getVideoStickers($, item, { staticProxy, index }) {
  return $(item).find('.js-videosticker_video')?.map((_index, video) => {
    const url = $(video)?.attr('src')
    const imgurl = $(video).find('img')?.attr('src')
    return `
    <div style="background-image: none; width: 256px;">
      <video src="${staticProxy + url}" width="100%" height="100%" alt="Video Sticker" preload muted autoplay loop playsinline disablepictureinpicture >
        <img class="sticker" src="${staticProxy + imgurl}" alt="Video Sticker" loading="${index > 15 ? 'eager' : 'lazy'}" />
      </video>
    </div>
    `
  })?.get()?.join('')
}

function getImageStickers($, item, { staticProxy, index }) {
  return $(item).find('.tgme_widget_message_sticker')?.map((_index, image) => {
    const url = $(image)?.attr('data-webp')
    return `<img class="sticker" src="${staticProxy + url}" style="width: 256px;" alt="Sticker" loading="${index > 15 ? 'eager' : 'lazy'}" />`
  })?.get()?.join('')
}

function getVideo($, item, { staticProxy, index }) {
  const video = $(item).find('.tgme_widget_message_video_wrap video')
  video?.attr('src', staticProxy + video?.attr('src'))
    ?.attr('controls', true)
    ?.attr('preload', index > 15 ? 'auto' : 'metadata')
    ?.attr('playsinline', true)
    .attr('webkit-playsinline', true)

  const roundVideo = $(item).find('.tgme_widget_message_roundvideo_wrap video')
  roundVideo?.attr('src', staticProxy + roundVideo?.attr('src'))
    ?.attr('controls', true)
    ?.attr('preload', index > 15 ? 'auto' : 'metadata')
    ?.attr('playsinline', true)
    .attr('webkit-playsinline', true)
  return $.html(video) + $.html(roundVideo)
}

function getAudio($, item, { staticProxy }) {
  const audio = $(item).find('.tgme_widget_message_voice')
  audio?.attr('src', staticProxy + audio?.attr('src'))
    ?.attr('controls', true)
  return $.html(audio)
}

function safeString(v) {
  return String(v || "").trim();
}

function toIntOrNull(v) {
  if (v === null || v === undefined) return null;
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return Math.trunc(n);
}

async getEntry(scopeType, scopeId, metricKey) {
    const st = safeString(scopeType);
    const sid = safeString(scopeId);
    const key = safeString(metricKey);
    if (!st || !sid || !key) return null;

    const row = await this.queryFirst(
      `SELECT * FROM ${DbTables.METRICS_CACHE} WHERE scope_type = ? AND scope_id = ? AND metric_key = ?`,
      [st, sid, key],
    );
    return row || null;
  }

async upsertEntry(params) {
    const st = safeString(params?.scopeType);
    const sid = safeString(params?.scopeId);
    const key = safeString(params?.metricKey);
    if (!st || !sid || !key) {
      return { changes: 0 };
    }

    const updatedAtMs = toIntOrNull(params?.updatedAtMs) ?? Date.now();

    const bind = [
      st,
      sid,
      key,
      toIntOrNull(params?.valueNum),
      params?.valueText ?? null,
      params?.valueJsonText ?? null,
      toIntOrNull(params?.snapshotAtMs),
      updatedAtMs,
      params?.errorMessage ?? null,
    ];

    const sql = `
      INSERT INTO ${DbTables.METRICS_CACHE} (
        scope_type, scope_id, metric_key,
        value_num, value_text, value_json_text,
        snapshot_at_ms, updated_at_ms,
        error_message
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(scope_type, scope_id, metric_key) DO UPDATE SET
        value_num = excluded.value_num,
        value_text = excluded.value_text,
        value_json_text = excluded.value_json_text,
        snapshot_at_ms = excluded.snapshot_at_ms,
        updated_at_ms = excluded.updated_at_ms,
        error_message = excluded.error_message
    `;

    const result = await this.db.prepare(sql).bind(...bind).run();
    return { changes: result?.meta?.changes ?? result?.changes ?? 0 };
  }

async deleteEntry(scopeType, scopeId, metricKey) {
    const st = safeString(scopeType);
    const sid = safeString(scopeId);
    const key = safeString(metricKey);
    if (!st || !sid || !key) return { changes: 0 };

    const result = await this.db
      .prepare(`DELETE FROM ${DbTables.METRICS_CACHE} WHERE scope_type = ? AND scope_id = ? AND metric_key = ?`)
      .bind(st, sid, key)
      .run();

    return { changes: result?.meta?.changes ?? result?.changes ?? 0 };
  }

