					item.useragent = item.useragent.replace(/Mac OS X [\d\.]+/, 'macOS');
					if (item.useragent.match(/\b(Other)\b/)) item.useragent = item.headers['user-agent'];
				});

				self.setCacheResponse(args, self.config.get('ttl'));

